			BK_LOGE(NULL, "ERROR: qspi_ll_wait_cmd_done timeout \n");
		}
		extern void bk_delay_us(UINT32 us);
		bk_delay_us(1);
	}
	hw->status_clr.clr_cmd_start_done = 1;
	hw->status_clr.clr_cmd_start_done = 0;
}

