void bk7258_i2c_sim_gpio_self_test(void)
{
  extern int printf(const char *fmt, ...);
  bool sda_read_high;
  bool sda_read_low;

  /* SCL: drive high/low, no independent readback pin available on this
   * bus topology to verify SCL's own level (no second wire), but at
   * least confirm the write calls do not fault/hang. */
  i2c_sim_scl_output();
  i2c_sim_scl_high();
  up_udelay(10);
  i2c_sim_scl_low();
  up_udelay(10);
  i2c_sim_scl_high();

  /* SDA: drive high, switch to input, read back; drive low (need to
   * switch back to output first), switch to input, read back.  If the
   * GPIO write path is broken (e.g. output not actually enabled), both
   * reads would likely show the same fixed level (either stuck at
   * whatever the external pull-up drives it to, or stuck low) regardless
   * of what we just drove. */
  i2c_sim_sda_output();
  i2c_sim_sda_high();
  up_udelay(10);
  i2c_sim_sda_input();
  up_udelay(10);
  sda_read_high = i2c_sim_sda_read();

  i2c_sim_sda_output();
  i2c_sim_sda_low();
  up_udelay(10);
  i2c_sim_sda_input();
  up_udelay(10);
  sda_read_low = i2c_sim_sda_read();

  printf("i2c_sim: gpio self test: after drive-high, sda reads %d "
         "(expect 1); after drive-low, sda reads %d (expect 0)\n",
         (int)sda_read_high, (int)sda_read_low);

  i2c_sim_scl_low();
  i2c_sim_sda_output();
  i2c_sim_sda_high();
}

