              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT |
              BK7258_GPIO_OUTPUT_DISABLE | BK7258_GPIO_PULL_ENABLE |
              BK7258_GPIO_SECOND_FUNCTION,
              setbits);
  leave_critical_section(flags);
}

void bk7258_gpio_write(unsigned int pin, bool value)
{
  if (value)
    {
      modifyreg32(BK7258_GPIO_CFG(pin), 0, BK7258_GPIO_OUTPUT);
    }
  else
    {
      modifyreg32(BK7258_GPIO_CFG(pin), BK7258_GPIO_OUTPUT, 0);
    }
}

bool bk7258_gpio_read(unsigned int pin)
{
  return (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_INPUT) != 0;
}

void bk7258_gpio_set_function(unsigned int pin, unsigned int function)
{
  irqstate_t flags;
  uintptr_t regaddr = BK7258_GPIO_SYS_CFG(pin);
  uint32_t shift = BK7258_GPIO_SYS_SHIFT(pin);

  flags = enter_critical_section();
  modifyreg32(regaddr, BK7258_GPIO_SYS_MASK(pin), (function & 0xfu) << shift);
  modifyreg32(BK7258_GPIO_CFG(pin),
              BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT |
              BK7258_GPIO_PULL_ENABLE,
              BK7258_GPIO_OUTPUT_DISABLE | BK7258_GPIO_SECOND_FUNCTION);
  leave_critical_section(flags);
}
/****************************************************************************
 * board/beken/chips/bk7258/bk7258_dma.c
 *
 * BK7258 minimal single-channel (channel 0), single-shot, memory-to-memory
 * DMA driver.  Register layout source: bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/dma_struct.h and hal/dma_ll.h.
 *
 * Register offsets (byte offset from BK7258_DMA_BASE, word index in
 * dma_hw_t from dma_struct.h in parentheses):
 *   config_group[0] starts at byte offset 0x40 (word index 0x10): the
 *   dma_hw_t header occupies 16 words (device_id, version_id, prio_mode,
 *   reg_gap_0, secure_attr, privileged_attr, int_status0~3, int_allocate,
 *   reg_gap_1[5] = 0x0..0xF).  Each channel occupies 16 words (0x40 bytes):
 *     ctrl              word 0  (REG_0x10) - bit[0] enable, bit[1]
 *                                finish_int_en, bit[3] mode(0=SINGLE),
 *                                bit[8] src_addr_inc_en, bit[9]
 *                                dest_addr_inc_en, bit[16:31] transfer_len
 *     dest_start_addr    word 1  (REG_0x11)
 *     src_start_addr     word 2  (REG_0x12)
 *     req_mux            word 7  (REG_0x17) - not used by this driver
 *                                (memory-to-memory transfer, matching
 *                                bk_dvp.c's encode_yuv_dma_cpy() which uses
 *                                DMA_DEV_DTCM on both ends and never touches
 *                                req_mux)
 *     status             word 12 (REG_0x1c) - bit[0:16] remain_len,
 *                                bit[18] finish_int
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <stdbool.h>
#include <stdint.h>

#include "arm_internal.h"
#include "irq.h"
#include "bk7258_dma.h"

#define BK7258_DMA_BASE            0x45020000u  /* SOC_GENER_DMA_REG_BASE */
#define BK7258_DMA_CHANNEL         0u

#define BK7258_DMA_CHAN_GROUP_BASE (BK7258_DMA_BASE + 0x40u)
#define BK7258_DMA_CHAN_STRIDE     0x40u  /* 16 words * 4 bytes per channel */

#define BK7258_DMA_REG(word_off)  (BK7258_DMA_CHAN_GROUP_BASE + \
                                    BK7258_DMA_CHANNEL * BK7258_DMA_CHAN_STRIDE + \
                                    (word_off) * 4u)

#define BK7258_DMA_CTRL            BK7258_DMA_REG(0)
#define BK7258_DMA_DEST_ADDR       BK7258_DMA_REG(1)
#define BK7258_DMA_SRC_ADDR        BK7258_DMA_REG(2)
#define BK7258_DMA_STATUS          BK7258_DMA_REG(12)

#define BK7258_DMA_CTRL_ENABLE          (1u << 0)
#define BK7258_DMA_CTRL_FINISH_INT_EN   (1u << 1)
#define BK7258_DMA_CTRL_MODE_SINGLE     (0u << 3)
#define BK7258_DMA_CTRL_SRC_INC_EN      (1u << 8)
#define BK7258_DMA_CTRL_DEST_INC_EN     (1u << 9)
#define BK7258_DMA_CTRL_LEN_SHIFT       16u
#define BK7258_DMA_CTRL_LEN_MASK        0xffffu

#define BK7258_DMA_STATUS_REMAIN_LEN_MASK 0x1ffffu
#define BK7258_DMA_STATUS_FINISH_INT      (1u << 18)

static bk7258_dma_done_cb_t g_done_cb;
static void *g_done_cb_arg;

static int bk7258_dma_isr(int irq, void *context, void *arg)
{
  uint32_t status = getreg32(BK7258_DMA_STATUS);

  if ((status & BK7258_DMA_STATUS_FINISH_INT) != 0)
    {
      /* Stop the channel (clears enable so a stale "finish" state from
       * this transfer does not confuse the next bk7258_dma_configure()
       * call) and acknowledge the finish flag by writing it back (the
       * status register's finish_int bit is part of the same word as
       * remain_len; per dma_struct.h there is no separate write-1-to-clear
       * register documented for this field in the excerpt reviewed, so we
       * rely on disabling the channel via ctrl.enable=0, which is what
       * bk_dvp.c's line-done handlers do via bk_dma_stop() before
       * reconfiguring for the next transfer). */
      modifyreg32(BK7258_DMA_CTRL, BK7258_DMA_CTRL_ENABLE, 0);

      if (g_done_cb != NULL)
        {
          g_done_cb(g_done_cb_arg);
        }
    }

  return 0;
}

void bk7258_dma_init(void)
{
  modifyreg32(BK7258_DMA_CTRL, BK7258_DMA_CTRL_ENABLE, 0);

  irq_attach(BK7258_IRQ_DMA, bk7258_dma_isr, NULL);
  up_enable_irq(BK7258_IRQ_DMA);
}

void bk7258_dma_configure(uint32_t src_addr, uint32_t dest_addr,
                           uint32_t transfer_len)
{
  uint32_t ctrl;
  uint32_t len_field;

  /* Ensure the channel is disabled before reprogramming, matching
   * bk_dvp.c's yuv_sm0_line_done()/yuv_sm1_line_done() pattern of calling
   * bk_dma_stop() before bk_dma_set_src_start_addr()/
   * bk_dma_set_dest_start_addr()/bk_dma_start() on each line-done
   * interrupt. */
  modifyreg32(BK7258_DMA_CTRL, BK7258_DMA_CTRL_ENABLE, 0);

  putreg32(src_addr, BK7258_DMA_SRC_ADDR);
  putreg32(dest_addr, BK7258_DMA_DEST_ADDR);

  /* transfer_len is in bytes (matching bk_dma_set_transfer_len()'s
   * "over 65536 bytes" bounds-check message).  The ctrl.transfer_len
   * register field encodes (byte_count - 1), per
   * dma_ll_set_transfer_len(): "ctrl.transfer_len = (tran_len - 1) &
   * 0xffff" (ap/middleware/soc/bk7258_ap/hal/dma_ll.h:371). */
  len_field = (transfer_len - 1u) & BK7258_DMA_CTRL_LEN_MASK;

  ctrl = BK7258_DMA_CTRL_MODE_SINGLE |
         BK7258_DMA_CTRL_SRC_INC_EN |
         BK7258_DMA_CTRL_DEST_INC_EN |
         BK7258_DMA_CTRL_FINISH_INT_EN |
         (len_field << BK7258_DMA_CTRL_LEN_SHIFT);

  putreg32(ctrl, BK7258_DMA_CTRL);
}

void bk7258_dma_set_done_callback(bk7258_dma_done_cb_t cb, void *arg)
{
  g_done_cb = cb;
  g_done_cb_arg = arg;
}

void bk7258_dma_start(void)
{
  modifyreg32(BK7258_DMA_CTRL, 0, BK7258_DMA_CTRL_ENABLE);
}

void bk7258_dma_stop(void)
{
  modifyreg32(BK7258_DMA_CTRL, BK7258_DMA_CTRL_ENABLE, 0);
}

bool bk7258_dma_is_busy(void)
{
  return (getreg32(BK7258_DMA_CTRL) & BK7258_DMA_CTRL_ENABLE) != 0;
}

uint32_t bk7258_dma_get_remain_len(void)
{
  return getreg32(BK7258_DMA_STATUS) & BK7258_DMA_STATUS_REMAIN_LEN_MASK;
}
/****************************************************************************
 * board/beken/chips/bk7258/bk7258_yuv_buf.c
 *
 * BK7258 YUV_BUF controller thin port, YUV direct-capture mode only.
 * Register layout source: bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/yuv_buf_struct.h and
 * ap/middleware/soc/bk7258_ap/hal/yuv_buf_ll.h.
 *
 * Register offsets (byte offset from BK7258_YUV_BUF_BASE, word index in
 * yuv_buf_hw_t from yuv_buf_struct.h in parentheses):
 *   global_ctrl  0x08 (REG_0x02) - bit[0] soft_reset, bit[1] clk_gate_bypass
 *   ctrl         0x10 (REG_0x04) - bit[0] yuv_mode, bit[12] h264_mode
 *   pixel        0x14 (REG_0x05) - bit[0:7] x_pixel, bit[8:15] y_pixel,
 *                                  bit[16:31] frame_blk
 *   em_base_addr 0x20 (REG_0x08)
 *   int_en       0x24 (REG_0x09) - bit[1] yuv_arv_int_en, bit[2]
 *                                  sm0_wr_int_en, bit[3] sm1_wr_int_en
 *   int_status   0x28 (REG_0x0a) - bit[1] yuv_arv_int, bit[2] sm0_wr_int,
 *                                  bit[3] sm1_wr_int
 *   emr_base_addr 0x30 (REG_0x0c)
 *
 * Pixel unit: x_pixel/y_pixel registers do not perform any unit
 * conversion themselves (yuv_buf_hal_set_config_common() writes
 * config->x_pixel/y_pixel directly).  The /8 conversion happens at the
 * application layer in bk_dvp.c ("yuv_mode_config.x_pixel =
 * config->width / 8"), so this driver's bk7258_yuv_buf_configure()
 * performs that same /8 conversion internally, taking real pixel
 * width/height as its parameters.  frame_blk = x_pixel * y_pixel / 2
 * (using the already-/8 x_pixel/y_pixel values).
 *
 * PSRAM line buffer: YUV direct-capture mode hard-codes
 * em_base_addr/emr_base_addr to SOC_PSRAM_DATA_BASE
 * (ap/middleware/soc/common/hal/yuv_buf_hal.c
 * yuv_buf_hal_set_yuv_mode_config(): "yuv_mode set em_base_addr as
 * psram"), not an application-supplied address.  This driver writes that
 * fixed address to both registers and exposes it via
 * bk7258_yuv_buf_get_line_buf_addr() for the caller to use as the DMA
 * source address.
 *
 * Interrupt: single hardware interrupt line (INT_SRC_YUVB, EXTIRQ=58,
 * NuttX IRQ=74) multiplexes several events via int_status bits; this
 * driver only handles sm0_wr_int/sm1_wr_int (line-done, fired every 8
 * lines) as a minimal smoke-test signal, per this bring-up milestone's
 * reduced scope (see bk7258_yuv_buf.h).  Interrupt status is cleared by
 * writing the read value back (write-1-to-clear), per
 * yuv_buf_ll_clear_interrupt_status().
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <stdint.h>

#include "arm_internal.h"
#include "hardware/bk7258_memorymap.h"
#include "irq.h"
#include "bk7258_yuv_buf.h"

#define BK7258_YUV_BUF_BASE        0x48020000u  /* SOC_YUV_BUF_REG_BASE */

#define YUV_BUF_REG(word_off)     (BK7258_YUV_BUF_BASE + (word_off) * 4u)

#define YUV_BUF_GLOBAL_CTRL        YUV_BUF_REG(2)
#define YUV_BUF_GLOBAL_CTRL_SOFT_RESET  (1u << 0)

#define YUV_BUF_CTRL               YUV_BUF_REG(4)
#define YUV_BUF_CTRL_YUV_MODE      (1u << 0)
#define YUV_BUF_CTRL_H264_MODE     (1u << 12)

#define YUV_BUF_PIXEL              YUV_BUF_REG(5)
#define YUV_BUF_PIXEL_X_SHIFT      0u
#define YUV_BUF_PIXEL_Y_SHIFT      8u
#define YUV_BUF_PIXEL_FRAME_BLK_SHIFT 16u

#define YUV_BUF_EM_BASE_ADDR       YUV_BUF_REG(8)
#define YUV_BUF_INT_EN             YUV_BUF_REG(9)
#define YUV_BUF_INT_EN_SM0_WR      (1u << 2)
#define YUV_BUF_INT_EN_SM1_WR      (1u << 3)

#define YUV_BUF_INT_STATUS         YUV_BUF_REG(10)
#define YUV_BUF_INT_STATUS_SM0_WR  (1u << 2)
#define YUV_BUF_INT_STATUS_SM1_WR  (1u << 3)

#define YUV_BUF_EMR_BASE_ADDR      YUV_BUF_REG(12)

/* SOC_PSRAM_DATA_BASE, ap/include/soc/bk7258/reg_base.h:43 */
#define YUV_BUF_PSRAM_LINE_BUF_ADDR 0x60000000u

static bk7258_yuv_buf_line_cb_t g_line_cb;
static void *g_line_cb_arg;

static int bk7258_yuv_buf_isr(int irq, void *context, void *arg)
{
  uint32_t status = getreg32(YUV_BUF_INT_STATUS);

  /* Write-1-to-clear: write back exactly the bits that were read as set,
   * per yuv_buf_ll_clear_interrupt_status(). */
  putreg32(status, YUV_BUF_INT_STATUS);

  if ((status & (YUV_BUF_INT_STATUS_SM0_WR | YUV_BUF_INT_STATUS_SM1_WR)) != 0)
    {
      if (g_line_cb != NULL)
        {
          g_line_cb(g_line_cb_arg);
        }
    }

  return 0;
}

void bk7258_yuv_buf_init(void)
{
  putreg32(YUV_BUF_GLOBAL_CTRL_SOFT_RESET, YUV_BUF_GLOBAL_CTRL);
  up_udelay(10);
  putreg32(0, YUV_BUF_GLOBAL_CTRL);

  irq_attach(BK7258_IRQ_YUVB, bk7258_yuv_buf_isr, NULL);
  up_enable_irq(BK7258_IRQ_YUVB);
}

void bk7258_yuv_buf_configure(uint16_t width, uint16_t height)
{
  uint32_t x_pixel = width / 8u;
  uint32_t y_pixel = height / 8u;
  uint32_t frame_blk = (x_pixel * y_pixel) / 2u;
  uint32_t pixel_reg;

  pixel_reg = (x_pixel << YUV_BUF_PIXEL_X_SHIFT) |
              (y_pixel << YUV_BUF_PIXEL_Y_SHIFT) |
              (frame_blk << YUV_BUF_PIXEL_FRAME_BLK_SHIFT);
  putreg32(pixel_reg, YUV_BUF_PIXEL);

  /* YUV direct-capture mode uses a fixed PSRAM line buffer address, not
   * an application-supplied one; see file header comment. */
  putreg32(YUV_BUF_PSRAM_LINE_BUF_ADDR, YUV_BUF_EM_BASE_ADDR);
  putreg32(YUV_BUF_PSRAM_LINE_BUF_ADDR, YUV_BUF_EMR_BASE_ADDR);

  putreg32(YUV_BUF_INT_EN_SM0_WR | YUV_BUF_INT_EN_SM1_WR, YUV_BUF_INT_EN);
}

uint32_t bk7258_yuv_buf_get_line_buf_addr(void)
{
  return YUV_BUF_PSRAM_LINE_BUF_ADDR;
}

void bk7258_yuv_buf_set_line_callback(bk7258_yuv_buf_line_cb_t cb, void *arg)
{
  g_line_cb = cb;
  g_line_cb_arg = arg;
}

void bk7258_yuv_buf_start(void)
{
  /* YUV direct-capture mode start = ctrl.yuv_mode=1, ctrl.h264_mode=0.
   * No separate "rencode start" trigger is needed (that bit is only used
   * by the JPEG/H264 encoder paths); per
   * yuv_buf_hal_start_yuv_mode(): "yuv_buf_ll_enable_yuv_buf_mode(hw);
   * yuv_buf_ll_disable_h264_encode_mode(hw);". */
  modifyreg32(YUV_BUF_CTRL, YUV_BUF_CTRL_H264_MODE, YUV_BUF_CTRL_YUV_MODE);
}

void bk7258_yuv_buf_stop(void)
{
  modifyreg32(YUV_BUF_CTRL, YUV_BUF_CTRL_YUV_MODE, 0);
}

