/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_gpio.c
 *
 * Unit tests for bk7258_gpio.c, compiled and linked against the real
 * production source file (not a reimplementation), with getreg32/
 * putreg32/modifyreg32 redirected to mock memory via sim_include/
 * arm_internal.h.  Verifies the actual bit-level register manipulation
 * this driver performs, cross-checked against the authoritative bit
 * positions from bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/gpio_struct.h (as already cited in
 * board/beken/chips/bk7258/hardware/bk7258_gpio.h's own comments and
 * this project's prior register-verification work):
 *   bit[0] gpio_input (R)      bit[1] gpio_output (R/W)
 *   bit[2] gpio_input_en (R/W) bit[3] gpio_output_en (R/W, LOW-active
 *                                     per gpio_ll.h's
 *                                     "GPIO output enbale low active"
 *                                     comment and gpio_ll_output_enable()'s
 *                                     inverting logic -- so a *set* bit[3]
 *                                     means output is DISABLED, matching
 *                                     this driver's BK7258_GPIO_OUTPUT_DISABLE
 *                                     naming)
 *   bit[4] gpio_pull_mode      bit[5] gpio_pull_mode_en
 *   bit[6] gpio_2_func_en (second/pinmux function enable)
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "hardware/bk7258_gpio.h"
#include "bk7258_gpio.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

#define TEST_PIN 5u

static void test_output_enable_sets_level_and_clears_conflicting_bits(void)
{
  uint32_t reg;

  bk7258_sim_reset();

  /* Pre-seed the register with bits that bk7258_gpio_output() must clear
   * (input_enable, output_disable, pull_enable, second_function), plus a
   * bit it must NOT touch (pull_mode, bit[4]) to catch an over-broad
   * mask. */
  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN),
                     BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT_DISABLE |
                     BK7258_GPIO_PULL_ENABLE | BK7258_GPIO_SECOND_FUNCTION |
                     BK7258_GPIO_PULL_UP);

  bk7258_gpio_output(TEST_PIN, true);

  reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((reg & BK7258_GPIO_OUTPUT) != 0,
        "expected OUTPUT bit set when driving high, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_INPUT_ENABLE) == 0,
        "expected INPUT_ENABLE cleared, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_OUTPUT_DISABLE) == 0,
        "expected OUTPUT_DISABLE cleared (output must be enabled), "
        "reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_PULL_ENABLE) == 0,
        "expected PULL_ENABLE cleared, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_SECOND_FUNCTION) == 0,
        "expected SECOND_FUNCTION cleared, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_PULL_UP) != 0,
        "expected PULL_UP bit left untouched by output(), reg=0x%x", reg);
}

static void test_output_low_clears_level_bit(void)
{
  uint32_t reg;

  bk7258_sim_reset();
  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN), BK7258_GPIO_OUTPUT);

  bk7258_gpio_output(TEST_PIN, false);

  reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((reg & BK7258_GPIO_OUTPUT) == 0,
        "expected OUTPUT bit cleared when driving low, reg=0x%x", reg);
}

static void test_write_only_touches_output_level_bit(void)
{
  uint32_t reg;

  bk7258_sim_reset();

  /* Seed every other bit set; bk7258_gpio_write() must leave them alone
   * (unlike bk7258_gpio_output(), it does not reconfigure direction/pull,
   * matching its documented "pure electrical level toggle, does not
   * change configuration" contract implied by its narrower register
   * mask compared to bk7258_gpio_output()). */
  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN),
                     BK7258_GPIO_INPUT_ENABLE | BK7258_GPIO_OUTPUT_DISABLE |
                     BK7258_GPIO_PULL_ENABLE | BK7258_GPIO_SECOND_FUNCTION |
                     BK7258_GPIO_PULL_UP);

  bk7258_gpio_write(TEST_PIN, true);

  reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((reg & BK7258_GPIO_OUTPUT) != 0,
        "expected OUTPUT bit set, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_INPUT_ENABLE) != 0,
        "expected write() to leave INPUT_ENABLE untouched, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_OUTPUT_DISABLE) != 0,
        "expected write() to leave OUTPUT_DISABLE untouched, reg=0x%x",
        reg);
  CHECK((reg & BK7258_GPIO_PULL_ENABLE) != 0,
        "expected write() to leave PULL_ENABLE untouched, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_SECOND_FUNCTION) != 0,
        "expected write() to leave SECOND_FUNCTION untouched, reg=0x%x",
        reg);

  bk7258_gpio_write(TEST_PIN, false);
  reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((reg & BK7258_GPIO_OUTPUT) == 0,
        "expected OUTPUT bit cleared after write(false), reg=0x%x", reg);
}

static void test_read_reflects_input_bit(void)
{
  bk7258_sim_reset();

  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN), BK7258_GPIO_INPUT);
  CHECK(bk7258_gpio_read(TEST_PIN) == true,
        "expected read() true when INPUT bit set");

  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN), 0);
  CHECK(bk7258_gpio_read(TEST_PIN) == false,
        "expected read() false when INPUT bit clear");

  /* read() must only look at bit[0]; other set bits must not leak into
   * the boolean result via a too-broad mask. */
  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN), 0xfffffffeu);
  CHECK(bk7258_gpio_read(TEST_PIN) == false,
        "expected read() false when only non-INPUT bits are set "
        "(mask must be exactly bit[0])");
}

static void test_input_pullup_sets_input_mode_and_pullup(void)
{
  uint32_t reg;

  bk7258_sim_reset();
  bk7258_sim_poke32(BK7258_GPIO_CFG(TEST_PIN),
                     BK7258_GPIO_OUTPUT | BK7258_GPIO_SECOND_FUNCTION);

  bk7258_gpio_input_pullup(TEST_PIN);

  reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((reg & BK7258_GPIO_INPUT_ENABLE) != 0,
        "expected INPUT_ENABLE set, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_OUTPUT_DISABLE) != 0,
        "expected OUTPUT_DISABLE set (output must be disabled while "
        "acting as input), reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_PULL_UP) != 0,
        "expected PULL_UP set, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_PULL_ENABLE) != 0,
        "expected PULL_ENABLE set, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_OUTPUT) == 0,
        "expected OUTPUT level bit cleared, reg=0x%x", reg);
  CHECK((reg & BK7258_GPIO_SECOND_FUNCTION) == 0,
        "expected SECOND_FUNCTION cleared, reg=0x%x", reg);
}

static void test_set_function_writes_pinmux_and_clears_gpio_mode(void)
{
  uint32_t sys_reg;
  uint32_t cfg_reg;
  uint32_t shift = BK7258_GPIO_SYS_SHIFT(TEST_PIN);

  bk7258_sim_reset();

  /* Pinmux register: pre-seed adjacent nibbles (for pins sharing the same
   * 32-bit sys-config word) to verify set_function() only touches this
   * pin's own 4-bit field, not neighboring pins packed into the same
   * word (BK7258_GPIO_SYS_CFG groups 8 pins per word, 4 bits each). */
  bk7258_sim_poke32(BK7258_GPIO_SYS_CFG(TEST_PIN), 0xffffffffu);

  bk7258_gpio_set_function(TEST_PIN, 3u);

  sys_reg = bk7258_sim_peek32(BK7258_GPIO_SYS_CFG(TEST_PIN));
  CHECK(((sys_reg >> shift) & 0xfu) == 3u,
        "expected function index 3 written to pin %u's 4-bit field, "
        "got %u", TEST_PIN, (unsigned int)((sys_reg >> shift) & 0xfu));
  CHECK((sys_reg & ~(0xfu << shift)) == (0xffffffffu & ~(0xfu << shift)),
        "expected set_function() to leave neighboring pins' bits in the "
        "same sys-config word untouched, sys_reg=0x%x", sys_reg);

  cfg_reg = bk7258_sim_peek32(BK7258_GPIO_CFG(TEST_PIN));
  CHECK((cfg_reg & BK7258_GPIO_SECOND_FUNCTION) != 0,
        "expected SECOND_FUNCTION set on the pin's own cfg register "
        "after set_function(), cfg_reg=0x%x", cfg_reg);
  CHECK((cfg_reg & BK7258_GPIO_INPUT_ENABLE) == 0,
        "expected INPUT_ENABLE cleared (pin now driven by the peripheral, "
        "not plain GPIO input), cfg_reg=0x%x", cfg_reg);
  CHECK((cfg_reg & BK7258_GPIO_OUTPUT) == 0,
        "expected OUTPUT level bit cleared, cfg_reg=0x%x", cfg_reg);
  CHECK((cfg_reg & BK7258_GPIO_PULL_ENABLE) == 0,
        "expected PULL_ENABLE cleared, cfg_reg=0x%x", cfg_reg);
  CHECK((cfg_reg & BK7258_GPIO_OUTPUT_DISABLE) != 0,
        "expected OUTPUT_DISABLE set (peripheral drives the pad, not "
        "this GPIO's own output driver), cfg_reg=0x%x", cfg_reg);
}

static void test_set_function_pins_in_different_words_are_independent(void)
{
  /* Pin 5 and pin 13 fall in different 8-pin sys-config words
   * (BK7258_GPIO_SYS_CFG(pin) = base + (pin>>3)*4); verify programming
   * one does not perturb the other, since they are stored in physically
   * distinct 32-bit registers. */
  const unsigned int pin_a = 5u;
  const unsigned int pin_b = 13u;

  bk7258_sim_reset();

  bk7258_gpio_set_function(pin_a, 7u);
  bk7258_gpio_set_function(pin_b, 9u);

  CHECK(((bk7258_sim_peek32(BK7258_GPIO_SYS_CFG(pin_a)) >>
          BK7258_GPIO_SYS_SHIFT(pin_a)) & 0xfu) == 7u,
        "expected pin_a's function to still read back as 7 after "
        "programming pin_b");
  CHECK(((bk7258_sim_peek32(BK7258_GPIO_SYS_CFG(pin_b)) >>
          BK7258_GPIO_SYS_SHIFT(pin_b)) & 0xfu) == 9u,
        "expected pin_b's function to read back as 9");
  CHECK(BK7258_GPIO_SYS_CFG(pin_a) != BK7258_GPIO_SYS_CFG(pin_b),
        "expected pin_a and pin_b to live in different sys-config words "
        "for this test to be meaningful");
}

int main(void)
{
  test_output_enable_sets_level_and_clears_conflicting_bits();
  test_output_low_clears_level_bit();
  test_write_only_touches_output_level_bit();
  test_read_reflects_input_bit();
  test_input_pullup_sets_input_mode_and_pullup();
  test_set_function_writes_pinmux_and_clears_gpio_mode();
  test_set_function_pins_in_different_words_are_independent();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_gpio.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

