/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_i2c_sim.c
 *
 * Protocol-level tests for bk7258_i2c_sim.c, compiled against the real
 * production source (bk7258_i2c_sim.c + bk7258_gpio.c, unmodified).
 *
 * Test strategy: a mock I2C slave is implemented as a write-hook +
 * read-hook pair on the mock GPIO registers (see sim_stubs.h).  The mock
 * slave watches every SCL/SDA register write the driver makes (via the
 * write hook), reconstructs the bit stream exactly as a real slave IC
 * would (sampling SDA on SCL's rising edge), and reacts in real time:
 * driving SDA low during the 9th clock's ACK window if the byte just
 * clocked in matches an address it's listening for, or answering a
 * read request with a chosen data byte, bit by bit, via the read hook.
 * This validates the driver's actual bit-level timing and sequencing,
 * not just its final return value -- a bug in bit order, clock-edge
 * sampling point, or ACK-window positioning would cause the mock slave
 * to reconstruct the wrong byte and the test to fail, exactly as a real
 * GC2145 sensor would fail to respond to a malformed transaction.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "hardware/bk7258_gpio.h"
#include "bk7258_gpio.h"
#include "bk7258_i2c_sim.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

#define I2C_SIM_SCL_PIN 0u
#define I2C_SIM_SDA_PIN 1u

/* ========================================================================
 * Mock I2C slave: a small bit-level state machine driven by the write
 * hook (observes every SCL/SDA register write) and the read hook
 * (drives SDA during the master's read windows: ACK bits and read-mode
 * data bits).
 * ======================================================================== */

typedef enum
{
  SLAVE_IDLE,       /* waiting for START */
  SLAVE_ADDR_BIT,   /* clocking in the 7-bit address + R/W bit */
  SLAVE_ADDR_ACK,   /* master is reading our ACK/NACK for the address */
  SLAVE_DATA_BIT,   /* clocking in a data/register-address byte (write) */
  SLAVE_DATA_ACK,   /* master is reading our ACK/NACK for a written byte */
  SLAVE_READ_BIT,   /* we are driving a data bit for the master to read */
  SLAVE_READ_ACK    /* master is driving its ACK/NACK for our byte (we
                      * just observe, do not react) */
} slave_state_t;

typedef struct
{
  slave_state_t state;
  uint8_t bit_count;      /* bits clocked in/out in the current byte */
  uint8_t shift_reg;      /* byte being assembled (address/write data) or
                            * sent (read data) */
  bool last_scl;
  bool last_sda;
  bool started;

  uint8_t match_addr_byte; /* 8-bit address+R/W byte this slave answers
                             * to; 0xFF disables address matching (never
                             * ACK) for the "sensor absent" test case */
  bool addr_matched_this_txn;

  uint8_t read_data;       /* byte to return for a read transaction */
  uint8_t read_bit_index;  /* 0..7, MSB first, valid while
                             * state==SLAVE_READ_BIT/SLAVE_READ_ACK */

  /* Recorded history, for tests that want to assert on the exact bytes
   * a write transaction clocked out (address byte + N data bytes), in
   * order -- this is the actual end-to-end proof that
   * bk7258_i2c_sim_write_reg()'s bit-banging produces a byte stream a
   * real slave would decode correctly. */
  uint8_t captured_bytes[8];
  uint8_t captured_count;
} mock_slave_t;

static mock_slave_t g_slave;

static void mock_slave_reset(uint8_t match_addr_byte, uint8_t read_data)
{
  memset(&g_slave, 0, sizeof(g_slave));
  g_slave.state = SLAVE_IDLE;
  g_slave.match_addr_byte = match_addr_byte;
  g_slave.read_data = read_data;
}

static void mock_slave_capture_byte(uint8_t byte)
{
  if (g_slave.captured_count < sizeof(g_slave.captured_bytes))
    {
      g_slave.captured_bytes[g_slave.captured_count++] = byte;
    }
}

/* Called on every SCL falling edge while assembling an address or data
 * byte in write-direction: shift the just-sampled bit into shift_reg. */
static void mock_slave_on_bit_sampled(bool sda_level)
{
  g_slave.shift_reg = (uint8_t)((g_slave.shift_reg << 1) |
                                 (sda_level ? 1 : 0));
  g_slave.bit_count++;
}

/* The write hook: called after every mock GPIO register write.  Detects
 * START (SDA falls while SCL is high), STOP (SDA rises while SCL is
 * high), and SCL rising/falling edges, driving the slave state machine
 * accordingly.  This function only *observes* SCL transitions and SDA
 * transitions while SDA is master-driven (write direction); the actual
 * *driving* of SDA for ACK/read-data happens in the read hook, invoked
 * when the master switches SDA to input and calls bk7258_gpio_read(). */
static void mock_slave_write_hook(uintptr_t addr, uint32_t value, void *arg)
{
  bool scl;
  bool sda;
  bool scl_rising;
  bool scl_falling;

  (void)arg;

  if (addr == BK7258_GPIO_CFG(I2C_SIM_SCL_PIN))
    {
      scl = (value & BK7258_GPIO_OUTPUT) != 0;
    }
  else if (addr == BK7258_GPIO_CFG(I2C_SIM_SDA_PIN))
    {
      scl = g_slave.last_scl;
    }
  else
    {
      return;
    }

  sda = (bk7258_sim_peek32(BK7258_GPIO_CFG(I2C_SIM_SDA_PIN)) &
         BK7258_GPIO_OUTPUT) != 0;

  scl_rising = scl && !g_slave.last_scl;
  scl_falling = !scl && g_slave.last_scl;

  /* START condition: SDA falls while SCL stays high. */
  if (scl && g_slave.last_scl && !sda && g_slave.last_sda)
    {
      g_slave.started = true;
      g_slave.state = SLAVE_ADDR_BIT;
      g_slave.bit_count = 0;
      g_slave.shift_reg = 0;
      g_slave.addr_matched_this_txn = false;
    }
  /* STOP condition: SDA rises while SCL stays high. */
  else if (scl && g_slave.last_scl && sda && !g_slave.last_sda)
    {
      g_slave.started = false;
      g_slave.state = SLAVE_IDLE;
    }
  else if (scl_falling)
    {
      switch (g_slave.state)
        {
        case SLAVE_ADDR_BIT:
          mock_slave_on_bit_sampled(g_slave.last_sda);
          if (g_slave.bit_count == 8)
            {
              mock_slave_capture_byte(g_slave.shift_reg);
              g_slave.addr_matched_this_txn =
                (g_slave.shift_reg == g_slave.match_addr_byte);
              g_slave.state = SLAVE_ADDR_ACK;
              if ((g_slave.shift_reg & 0x01) != 0 &&
                  g_slave.addr_matched_this_txn)
                {
                  /* Read direction: after the ACK window, we'll be
                   * driving data bits. */
                  g_slave.read_bit_index = 0;
                }
            }
          break;

        case SLAVE_ADDR_ACK:
          g_slave.state = ((g_slave.shift_reg & 0x01) != 0 &&
                            g_slave.addr_matched_this_txn) ?
                           SLAVE_READ_BIT : SLAVE_DATA_BIT;
          g_slave.bit_count = 0;
          g_slave.shift_reg = 0;
          break;

        case SLAVE_DATA_BIT:
          mock_slave_on_bit_sampled(g_slave.last_sda);
          if (g_slave.bit_count == 8)
            {
              mock_slave_capture_byte(g_slave.shift_reg);
              g_slave.state = SLAVE_DATA_ACK;
            }
          break;

        case SLAVE_DATA_ACK:
          g_slave.state = SLAVE_DATA_BIT;
          g_slave.bit_count = 0;
          g_slave.shift_reg = 0;
          break;

        case SLAVE_READ_BIT:
          g_slave.read_bit_index++;
          if (g_slave.read_bit_index == 8)
            {
              g_slave.state = SLAVE_READ_ACK;
            }
          break;

        case SLAVE_READ_ACK:
          g_slave.state = SLAVE_IDLE;
          break;

        case SLAVE_IDLE:
        default:
          break;
        }
    }

  g_slave.last_scl = scl;
  g_slave.last_sda = sda;
  (void)scl_rising;
}

/* The read hook: called whenever the driver reads the SDA pin (i.e. is
 * sampling ACK, or a read-mode data bit).  Overrides the stored mock
 * value to reflect what the slave is actively driving, matching real
 * open-drain I2C behavior where the slave pulls SDA low to ACK/send a
 * 0 bit and releases it (pulled up externally, modeled here as "stays
 * high") to NACK/send a 1 bit. */
static uint32_t mock_slave_read_hook(uintptr_t addr, uint32_t stored_value,
                                      void *arg)
{
  (void)arg;

  if (addr != BK7258_GPIO_CFG(I2C_SIM_SDA_PIN))
    {
      return stored_value;
    }

  if (g_slave.state == SLAVE_ADDR_ACK || g_slave.state == SLAVE_DATA_ACK)
    {
      /* ACK = slave drives SDA low (BK7258_GPIO_INPUT bit clear). */
      return g_slave.addr_matched_this_txn ? 0u : BK7258_GPIO_INPUT;
    }

  if (g_slave.state == SLAVE_READ_BIT)
    {
      uint8_t bit = (uint8_t)((g_slave.read_data >>
                                (7 - g_slave.read_bit_index)) & 0x01u);
      return bit != 0 ? BK7258_GPIO_INPUT : 0u;
    }

  return stored_value;
}

static void install_mock_slave(uint8_t match_addr_byte, uint8_t read_data)
{
  mock_slave_reset(match_addr_byte, read_data);
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);
  bk7258_sim_set_read_hook(mock_slave_read_hook, NULL);
}

