static void test_write_reg_full_byte_stream_matches_slave_capture(void)
{
  bool ok;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x00u);
  bk7258_i2c_sim_init();

  ok = bk7258_i2c_sim_write_reg(0x3Cu, 0xFEu, 0xA5u);

  CHECK(ok == true,
        "expected write_reg() to succeed against a slave that ACKs its "
        "own address");
  CHECK(g_slave.captured_count == 3,
        "expected the mock slave to have observed exactly 3 bytes "
        "(address, register, value), observed %u",
        g_slave.captured_count);
  if (g_slave.captured_count == 3)
    {
      CHECK(g_slave.captured_bytes[0] == (0x3Cu << 1),
            "expected first byte on the wire to be the 7-bit address "
            "0x3C shifted left with write bit clear (0x78), got 0x%02x",
            g_slave.captured_bytes[0]);
      CHECK(g_slave.captured_bytes[1] == 0xFEu,
            "expected second byte on the wire to be the register "
            "address 0xFE, got 0x%02x", g_slave.captured_bytes[1]);
      CHECK(g_slave.captured_bytes[2] == 0xA5u,
            "expected third byte on the wire to be the value 0xA5, "
            "got 0x%02x", g_slave.captured_bytes[2]);
    }
}

static void test_write_reg_bit_pattern_all_zero_and_all_one_bytes(void)
{
  bool ok;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x00u);
  bk7258_i2c_sim_init();

  ok = bk7258_i2c_sim_write_reg(0x3Cu, 0x00u, 0xFFu);

  CHECK(ok == true, "expected write_reg() to succeed");
  if (g_slave.captured_count == 3)
    {
      CHECK(g_slave.captured_bytes[1] == 0x00u,
            "expected all-zero register-address byte to survive the "
            "bit-banging unchanged, got 0x%02x",
            g_slave.captured_bytes[1]);
      CHECK(g_slave.captured_bytes[2] == 0xFFu,
            "expected all-one value byte to survive the bit-banging "
            "unchanged, got 0x%02x", g_slave.captured_bytes[2]);
    }
}

static void
test_write_reg_alternating_bit_pattern_validates_bit_order(void)
{
  bool ok;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x00u);
  bk7258_i2c_sim_init();

  /* 0xA5 = 1010_0101 and 0x5A = 0101_1010 are bit-reversal-detecting
   * patterns: if the driver's send_byte() shifted bits out in the wrong
   * order (LSB-first instead of the required MSB-first per
   * sim_i2c_driver.c's I2cSend(), which starts at Mask=128 and shifts
   * right), 0xA5 would arrive at the slave as its bit-reversed value
   * (0xA5 reversed is 0xA5 itself, which is not discriminating -- use
   * 0x93/0xC9 instead, which are not bit-palindromes). */
  ok = bk7258_i2c_sim_write_reg(0x3Cu, 0x93u, 0xC9u);

  CHECK(ok == true, "expected write_reg() to succeed");
  if (g_slave.captured_count == 3)
    {
      CHECK(g_slave.captured_bytes[1] == 0x93u,
            "expected register-address byte 0x93 (10010011) to arrive "
            "unreversed -- got 0x%02x (0x93 bit-reversed would be "
            "0xC9, which would indicate a reversed shift direction)",
            g_slave.captured_bytes[1]);
      CHECK(g_slave.captured_bytes[2] == 0xC9u,
            "expected value byte 0xC9 (11001001) to arrive unreversed "
            "-- got 0x%02x (0xC9 bit-reversed would be 0x93)",
            g_slave.captured_bytes[2]);
    }
}

static void test_write_reg_fails_when_slave_address_does_not_match(void)
{
  bool ok;

  bk7258_sim_reset();
  /* Install a slave that only answers to address 0x50<<1, while the
   * driver is told to talk to 0x3C -- models "sensor is a different
   * I2C address than expected" or "no sensor present at all" (since a
   * non-matching mock slave never drives SDA low, behaving exactly
   * like an truly absent/unpowered device on an externally pulled-up
   * bus). */
  install_mock_slave(0x50u << 1, 0x00u);
  bk7258_i2c_sim_init();

  ok = bk7258_i2c_sim_write_reg(0x3Cu, 0xFEu, 0x00u);

  CHECK(ok == false,
        "expected write_reg() to fail when no slave on the bus "
        "matches the address being written to");
  CHECK(g_slave.captured_count == 1,
        "expected the transaction to stop after the unmatched address "
        "byte (no register/value bytes should have been clocked out "
        "since the master must abort on address NACK), captured %u "
        "bytes", g_slave.captured_count);
}

static void test_read_reg_returns_slave_data_byte(void)
{
  bool ok;
  uint8_t value = 0;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x7Bu);
  bk7258_i2c_sim_init();

  ok = bk7258_i2c_sim_read_reg(0x3Cu, 0xF0u, &value);

  CHECK(ok == true,
        "expected read_reg() to succeed against a slave that ACKs and "
        "provides data");
  CHECK(value == 0x7Bu,
        "expected read_reg() to return the exact byte the mock slave "
        "was configured to send (0x7B), got 0x%02x", value);
}

static void test_read_reg_write_phase_uses_write_address_write_bit(void)
{
  bool ok;
  uint8_t value = 0;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x11u);
  bk7258_i2c_sim_init();

  ok = bk7258_i2c_sim_read_reg(0x3Cu, 0x55u, &value);

  CHECK(ok == true, "expected read_reg() to succeed");
  /* read_reg() issues two START conditions: first a write-direction
   * address (to send the register address), then a repeated START with
   * a read-direction address.  The mock slave's captured_bytes only
   * records write-direction address+data bytes (SLAVE_ADDR_BIT/
   * SLAVE_DATA_BIT paths), so we expect exactly 2 entries: the
   * write-direction address byte, then the register address byte --
   * the read-direction address byte and the returned data byte are
   * driven via SLAVE_READ_BIT, not captured the same way, which is
   * itself a useful assertion surface: if the driver's read_reg() sent
   * the register address with the wrong R/W bit (e.g. reused the
   * write-direction address byte for the second START too, which would
   * be a protocol bug -- a real sensor's read command must swap to the
   * read address for the second phase), the mock slave's
   * addr_matched_this_txn logic (which checks R/W bit via
   * "shift_reg & 0x01") would drive it down the SLAVE_DATA_BIT path
   * instead of SLAVE_READ_BIT, and the returned value would be read as
   * all-1s (NACK'd/undriven) rather than the seeded 0x11, failing the
   * value check in test_read_reg_returns_slave_data_byte-style
   * assertions. */
  CHECK(g_slave.captured_count == 2,
        "expected exactly 2 write-direction bytes captured (write "
        "address, register address) before the driver issues the "
        "repeated START for the read phase, captured %u",
        g_slave.captured_count);
  if (g_slave.captured_count == 2)
    {
      CHECK(g_slave.captured_bytes[0] == (0x3Cu << 1),
            "expected first byte to be the write-direction address "
            "(R/W bit clear), got 0x%02x", g_slave.captured_bytes[0]);
      CHECK(g_slave.captured_bytes[1] == 0x55u,
            "expected second byte to be the register address 0x55, "
            "got 0x%02x", g_slave.captured_bytes[1]);
    }
  CHECK(value == 0x11u,
        "expected the read phase to have correctly used the "
        "read-direction address (R/W bit set) and received the "
        "slave's data byte 0x11, got 0x%02x -- a wrong R/W bit on the "
        "second START would cause this to fail", value);
}

static void test_multiple_transactions_do_not_leak_state(void)
{
  bool ok1;
  bool ok2;
  bool ok3;

  bk7258_sim_reset();
  install_mock_slave(0x3Cu << 1, 0x00u);
  bk7258_i2c_sim_init();

  ok1 = bk7258_i2c_sim_write_reg(0x3Cu, 0x01u, 0x11u);
  g_slave.captured_count = 0; /* reset capture between transactions */
  ok2 = bk7258_i2c_sim_write_reg(0x3Cu, 0x02u, 0x22u);
  g_slave.captured_count = 0;
  ok3 = bk7258_i2c_sim_write_reg(0x3Cu, 0x03u, 0x33u);

  CHECK(ok1 && ok2 && ok3,
        "expected 3 consecutive write_reg() calls to all succeed "
        "(each STARTs and STOPs cleanly, matching real sensor "
        "initialization sequences of hundreds of consecutive register "
        "writes, as bk7258_gc2145.c performs)");
  CHECK(g_slave.captured_count == 3,
        "expected the third transaction's captured bytes to be exactly "
        "that transaction's own 3 bytes (address+2 data), not "
        "accumulated across all 3 calls, got %u",
        g_slave.captured_count);
  if (g_slave.captured_count == 3)
    {
      CHECK(g_slave.captured_bytes[1] == 0x03u &&
            g_slave.captured_bytes[2] == 0x33u,
            "expected the third transaction's register/value bytes to "
            "be 0x03/0x33, got 0x%02x/0x%02x",
            g_slave.captured_bytes[1], g_slave.captured_bytes[2]);
    }
}

int main(void)
{
  test_write_reg_full_byte_stream_matches_slave_capture();
  test_write_reg_bit_pattern_all_zero_and_all_one_bytes();
  test_write_reg_alternating_bit_pattern_validates_bit_order();
  test_write_reg_fails_when_slave_address_does_not_match();
  test_read_reg_returns_slave_data_byte();
  test_read_reg_write_phase_uses_write_address_write_bit();
  test_multiple_transactions_do_not_leak_state();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_i2c_sim.c protocol tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

