/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_dma.c
 *
 * Unit tests for bk7258_dma.c, compiled against the real production
 * source (unmodified), verifying register configuration and the
 * completion interrupt path.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "bk7258_dma.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

/* Mirrors bk7258_dma.c's private register layout (byte offsets from the
 * DMA base) so tests can inspect the exact bits the driver wrote,
 * without the driver needing to expose any test-only getters.  Any
 * mismatch here versus the driver's own #defines would show up as test
 * failures, which is the point: this is an independent cross-check of
 * the driver's documented register map. */
#define TEST_DMA_BASE            0x45020000u
#define TEST_DMA_CHAN0_BASE      (TEST_DMA_BASE + 0x40u)
#define TEST_DMA_CTRL            (TEST_DMA_CHAN0_BASE + 0u * 4u)
#define TEST_DMA_DEST_ADDR       (TEST_DMA_CHAN0_BASE + 1u * 4u)
#define TEST_DMA_SRC_ADDR        (TEST_DMA_CHAN0_BASE + 2u * 4u)
#define TEST_DMA_STATUS          (TEST_DMA_CHAN0_BASE + 12u * 4u)

#define TEST_DMA_CTRL_ENABLE          (1u << 0)
#define TEST_DMA_CTRL_FINISH_INT_EN   (1u << 1)
#define TEST_DMA_CTRL_MODE_BIT        (1u << 3)
#define TEST_DMA_CTRL_SRC_INC_EN      (1u << 8)
#define TEST_DMA_CTRL_DEST_INC_EN     (1u << 9)
#define TEST_DMA_CTRL_LEN_SHIFT       16u

#define TEST_DMA_STATUS_FINISH_INT    (1u << 18)

static void test_configure_writes_addresses_and_ctrl_fields(void)
{
  uint32_t ctrl;
  uint32_t src;
  uint32_t dest;

  bk7258_sim_reset();

  bk7258_dma_configure(0x60000000u, 0x28100000u, 10240u);

  src = bk7258_sim_peek32(TEST_DMA_SRC_ADDR);
  dest = bk7258_sim_peek32(TEST_DMA_DEST_ADDR);
  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);

  CHECK(src == 0x60000000u,
        "expected src_start_addr register to hold the exact source "
        "address passed in, got 0x%x", src);
  CHECK(dest == 0x28100000u,
        "expected dest_start_addr register to hold the exact "
        "destination address passed in, got 0x%x", dest);
  CHECK((ctrl & TEST_DMA_CTRL_MODE_BIT) == 0,
        "expected SINGLE mode (mode bit clear), ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_SRC_INC_EN) != 0,
        "expected source address auto-increment enabled, ctrl=0x%x",
        ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_DEST_INC_EN) != 0,
        "expected destination address auto-increment enabled, "
        "ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_FINISH_INT_EN) != 0,
        "expected finish interrupt enabled, ctrl=0x%x", ctrl);
}

static void test_configure_encodes_transfer_len_minus_one(void)
{
  uint32_t ctrl;
  uint32_t len_field;

  bk7258_sim_reset();

  /* Per dma_ll_set_transfer_len() in the authoritative reference
   * (ap/middleware/soc/bk7258_ap/hal/dma_ll.h:371): "ctrl.transfer_len =
   * (tran_len - 1) & 0xffff" -- the register field encodes byte count
   * minus one, not the raw byte count.  This is the exact detail that
   * would silently transfer one byte short (or, worse, wrap to 0xffff
   * and transfer 65536 bytes) if a future edit reverted to a naive
   * "just write transfer_len" implementation. */
  bk7258_dma_configure(0u, 0u, 10240u);

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  len_field = (ctrl >> TEST_DMA_CTRL_LEN_SHIFT) & 0xffffu;

  CHECK(len_field == 10240u - 1u,
        "expected ctrl.transfer_len field to encode (10240-1)=10239, "
        "got %u", len_field);
}

static void test_configure_transfer_len_one_byte_edge_case(void)
{
  uint32_t ctrl;
  uint32_t len_field;

  bk7258_sim_reset();

  /* transfer_len=1 is the smallest legal transfer; (1-1)=0 must not
   * underflow to a large value. */
  bk7258_dma_configure(0u, 0u, 1u);

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  len_field = (ctrl >> TEST_DMA_CTRL_LEN_SHIFT) & 0xffffu;

  CHECK(len_field == 0u,
        "expected ctrl.transfer_len field to be 0 for a 1-byte "
        "transfer ((1-1)=0), got %u", len_field);
}

static void test_start_sets_enable_bit_without_touching_addresses(void)
{
  uint32_t ctrl;
  uint32_t src_before;
  uint32_t dest_before;

  bk7258_sim_reset();
  bk7258_dma_configure(0x11111111u, 0x22222222u, 100u);
  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) == 0,
        "expected configure() to leave the channel disabled until "
        "start() is called, ctrl=0x%x", ctrl);

  src_before = bk7258_sim_peek32(TEST_DMA_SRC_ADDR);
  dest_before = bk7258_sim_peek32(TEST_DMA_DEST_ADDR);

  bk7258_dma_start();

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) != 0,
        "expected start() to set the enable bit, ctrl=0x%x", ctrl);
  CHECK(bk7258_sim_peek32(TEST_DMA_SRC_ADDR) == src_before,
        "expected start() to leave src_start_addr untouched");
  CHECK(bk7258_sim_peek32(TEST_DMA_DEST_ADDR) == dest_before,
        "expected start() to leave dest_start_addr untouched");
}

static void test_stop_clears_enable_bit(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_dma_configure(0u, 0u, 100u);
  bk7258_dma_start();

  bk7258_dma_stop();

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) == 0,
        "expected stop() to clear the enable bit, ctrl=0x%x", ctrl);
}

static void test_is_busy_reflects_enable_bit(void)
{
  bk7258_sim_reset();
  bk7258_dma_configure(0u, 0u, 100u);

  CHECK(bk7258_dma_is_busy() == false,
        "expected is_busy() false before start()");

  bk7258_dma_start();
  CHECK(bk7258_dma_is_busy() == true,
        "expected is_busy() true after start()");

  bk7258_dma_stop();
  CHECK(bk7258_dma_is_busy() == false,
        "expected is_busy() false after stop()");
}

static void test_configure_disables_channel_before_reprogramming(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_dma_configure(0u, 0u, 100u);
  bk7258_dma_start();
  CHECK(bk7258_dma_is_busy() == true, "expected channel running");

  /* Per bk_dvp.c's yuv_sm0_line_done()/yuv_sm1_line_done() pattern (stop
   * before reprogramming src/dest for the next line), configure() must
   * itself disable the channel before writing new addresses/ctrl, so a
   * caller does not need to remember to call stop() first every time it
   * reconfigures a still-running transfer between successive line-done
   * interrupts. */
  bk7258_dma_configure(0x99999999u, 0x88888888u, 200u);

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) == 0,
        "expected configure() to disable the channel even if it was "
        "left running from a prior transfer, ctrl=0x%x", ctrl);
}

static void test_get_remain_len_masks_only_remain_len_bits(void)
{
  uint32_t remain;

  bk7258_sim_reset();

  /* Seed status with remain_len=0 plus every bit outside the 17-bit
   * remain_len field set, to catch an over-broad mask. */
  bk7258_sim_poke32(TEST_DMA_STATUS, 0xfffe0000u);

  remain = bk7258_dma_get_remain_len();

  CHECK(remain == 0u,
        "expected get_remain_len() to mask out all bits above bit[16], "
        "got 0x%x", remain);

  bk7258_sim_poke32(TEST_DMA_STATUS, 0x1ffffu);
  remain = bk7258_dma_get_remain_len();
  CHECK(remain == 0x1ffffu,
        "expected get_remain_len() to return the full 17-bit field "
        "when all its bits are set, got 0x%x", remain);
}

static void test_init_registers_and_enables_irq(void)
{
  bk7258_sim_reset();

  bk7258_dma_init();

  CHECK(bk7258_sim_irq_is_enabled(BK7258_IRQ_DMA) == true,
        "expected init() to call up_enable_irq(BK7258_IRQ_DMA)");
}

static bool g_done_cb_called;
static void *g_done_cb_arg_seen;

static void test_done_cb(void *arg)
{
  g_done_cb_called = true;
  g_done_cb_arg_seen = arg;
}

static void test_isr_invokes_callback_only_on_finish_bit(void)
{
  int dummy_arg = 42;
  bool fired;

  bk7258_sim_reset();
  bk7258_dma_init();
  bk7258_dma_set_done_callback(test_done_cb, &dummy_arg);
  g_done_cb_called = false;
  g_done_cb_arg_seen = NULL;

  /* Status register with finish_int NOT set: ISR must not invoke the
   * callback (e.g. a spurious/other-bit interrupt should not be
   * misreported as "transfer complete"). */
  bk7258_sim_poke32(TEST_DMA_STATUS, 0u);
  fired = bk7258_sim_irq_fire(BK7258_IRQ_DMA);
  CHECK(fired == true, "expected an ISR to be registered for IRQ_DMA");
  CHECK(g_done_cb_called == false,
        "expected the done callback NOT to fire when finish_int is "
        "clear in the status register");

  /* Now set finish_int: the ISR must invoke the callback with the
   * exact arg pointer that was registered. */
  bk7258_sim_poke32(TEST_DMA_STATUS, TEST_DMA_STATUS_FINISH_INT);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_DMA);
  CHECK(g_done_cb_called == true,
        "expected the done callback to fire when finish_int is set");
  CHECK(g_done_cb_arg_seen == &dummy_arg,
        "expected the callback to receive the exact arg pointer "
        "registered via set_done_callback()");
}

static void test_isr_disables_channel_on_finish(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_dma_init();
  bk7258_dma_configure(0u, 0u, 100u);
  bk7258_dma_start();
  CHECK(bk7258_dma_is_busy() == true, "expected channel running");

  bk7258_sim_poke32(TEST_DMA_STATUS, TEST_DMA_STATUS_FINISH_INT);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_DMA);

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) == 0,
        "expected the ISR to clear the enable bit on a finish "
        "interrupt (so a subsequent configure()/start() cycle for the "
        "next line does not race with a still-enabled channel), "
        "ctrl=0x%x", ctrl);
}

int main(void)
{
  test_configure_writes_addresses_and_ctrl_fields();
  test_configure_encodes_transfer_len_minus_one();
  test_configure_transfer_len_one_byte_edge_case();
  test_start_sets_enable_bit_without_touching_addresses();
  test_stop_clears_enable_bit();
  test_is_busy_reflects_enable_bit();
  test_configure_disables_channel_before_reprogramming();
  test_get_remain_len_masks_only_remain_len_bits();
  test_init_registers_and_enables_irq();
  test_isr_invokes_callback_only_on_finish_bit();
  test_isr_disables_channel_on_finish();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_dma.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

