/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_yuv_buf.c
 *
 * Unit tests for bk7258_yuv_buf.c, compiled against the real production
 * source (unmodified).  Verifies pixel/8 conversion, frame_blk
 * calculation, the fixed-PSRAM-address line buffer configuration,
 * yuv_mode/h264_mode bit handling, line-done interrupt dispatch (via
 * sm0_wr/sm1_wr), and write-1-to-clear interrupt acknowledgment.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "bk7258_yuv_buf.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

/* Mirrors bk7258_yuv_buf.c's private register layout as an independent
 * cross-check (see test_dma.c's header comment for the same rationale). */
#define TEST_YUV_BUF_BASE          0x48020000u
#define TEST_YUV_BUF_REG(word_off) (TEST_YUV_BUF_BASE + (word_off) * 4u)

#define TEST_YUV_BUF_GLOBAL_CTRL   TEST_YUV_BUF_REG(2)
#define TEST_YUV_BUF_GLOBAL_CTRL_SOFT_RESET (1u << 0)

#define TEST_YUV_BUF_CTRL          TEST_YUV_BUF_REG(4)
#define TEST_YUV_BUF_CTRL_YUV_MODE  (1u << 0)
#define TEST_YUV_BUF_CTRL_H264_MODE (1u << 12)

#define TEST_YUV_BUF_PIXEL         TEST_YUV_BUF_REG(5)

#define TEST_YUV_BUF_EM_BASE_ADDR  TEST_YUV_BUF_REG(8)
#define TEST_YUV_BUF_INT_EN        TEST_YUV_BUF_REG(9)
#define TEST_YUV_BUF_INT_EN_SM0_WR (1u << 2)
#define TEST_YUV_BUF_INT_EN_SM1_WR (1u << 3)

#define TEST_YUV_BUF_INT_STATUS    TEST_YUV_BUF_REG(10)
#define TEST_YUV_BUF_INT_STATUS_SM0_WR (1u << 2)
#define TEST_YUV_BUF_INT_STATUS_SM1_WR (1u << 3)
#define TEST_YUV_BUF_INT_STATUS_YUV_ARV (1u << 1)

#define TEST_YUV_BUF_EMR_BASE_ADDR TEST_YUV_BUF_REG(12)

#define TEST_PSRAM_LINE_BUF_ADDR   0x60000000u

static void test_configure_640x480_pixel_register(void)
{
  uint32_t pixel_reg;
  uint32_t x_pixel;
  uint32_t y_pixel;
  uint32_t frame_blk;

  bk7258_sim_reset();

  /* 640/8=80, 480/8=60, frame_blk=(80*60)/2=2400, matching bk_dvp.c's
   * "yuv_mode_config.x_pixel = config->width / 8" convention (the /8
   * conversion happens at the application layer, not in the register
   * itself -- see bk7258_yuv_buf.c's file header comment citing
   * yuv_buf_hal_set_config_common(), which writes config->x_pixel
   * directly with no further scaling). */
  bk7258_yuv_buf_configure(640, 480);

  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  x_pixel = pixel_reg & 0xffu;
  y_pixel = (pixel_reg >> 8) & 0xffu;
  frame_blk = (pixel_reg >> 16) & 0xffffu;

  CHECK(x_pixel == 80u,
        "expected x_pixel = 640/8 = 80, got %u", x_pixel);
  CHECK(y_pixel == 60u,
        "expected y_pixel = 480/8 = 60, got %u", y_pixel);
  CHECK(frame_blk == 2400u,
        "expected frame_blk = (80*60)/2 = 2400, got %u", frame_blk);
}

static void test_configure_other_resolutions(void)
{
  uint32_t pixel_reg;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(864, 480);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 108u,
        "expected x_pixel = 864/8 = 108 for 864x480, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 60u,
        "expected y_pixel = 480/8 = 60 for 864x480, got %u",
        (pixel_reg >> 8) & 0xffu);

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(1280, 720);
  pixel_reg = bk7258_sim_peek32(TEST_YUV_BUF_PIXEL);
  CHECK((pixel_reg & 0xffu) == 160u,
        "expected x_pixel = 1280/8 = 160 for 1280x720, got %u",
        pixel_reg & 0xffu);
  CHECK(((pixel_reg >> 8) & 0xffu) == 90u,
        "expected y_pixel = 720/8 = 90 for 1280x720, got %u",
        (pixel_reg >> 8) & 0xffu);
}

static void test_configure_writes_fixed_psram_line_buffer_address(void)
{
  bk7258_sim_reset();

  /* YUV direct-capture mode hard-codes em_base_addr/emr_base_addr to
   * SOC_PSRAM_DATA_BASE regardless of resolution -- this is not an
   * application-supplied address (see bk7258_yuv_buf.c's file header
   * comment citing yuv_buf_hal_set_yuv_mode_config()'s "yuv_mode set
   * em_base_addr as psram" comment in the upstream reference). */
  bk7258_yuv_buf_configure(640, 480);

  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected em_base_addr to be the fixed PSRAM address 0x%x, "
        "got 0x%x", TEST_PSRAM_LINE_BUF_ADDR,
        bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR));
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected emr_base_addr to also be the fixed PSRAM address "
        "0x%x, got 0x%x", TEST_PSRAM_LINE_BUF_ADDR,
        bk7258_sim_peek32(TEST_YUV_BUF_EMR_BASE_ADDR));

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(1280, 720);
  CHECK(bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR) ==
        TEST_PSRAM_LINE_BUF_ADDR,
        "expected em_base_addr to remain the fixed PSRAM address "
        "regardless of resolution (1280x720 case), got 0x%x",
        bk7258_sim_peek32(TEST_YUV_BUF_EM_BASE_ADDR));
}

static void test_get_line_buf_addr_matches_register_value(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  CHECK(bk7258_yuv_buf_get_line_buf_addr() == TEST_PSRAM_LINE_BUF_ADDR,
        "expected get_line_buf_addr() to return the same fixed PSRAM "
        "address written to em_base_addr, got 0x%x",
        bk7258_yuv_buf_get_line_buf_addr());
}

static void test_configure_enables_line_done_interrupts(void)
{
  uint32_t int_en;

  bk7258_sim_reset();
  bk7258_yuv_buf_configure(640, 480);

  int_en = bk7258_sim_peek32(TEST_YUV_BUF_INT_EN);
  CHECK((int_en & TEST_YUV_BUF_INT_EN_SM0_WR) != 0,
        "expected sm0_wr_int_en to be set, int_en=0x%x", int_en);
  CHECK((int_en & TEST_YUV_BUF_INT_EN_SM1_WR) != 0,
        "expected sm1_wr_int_en to be set, int_en=0x%x", int_en);
}

static void test_start_sets_yuv_mode_clears_h264_mode(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();

  /* Pre-seed h264_mode set, to verify start() actively clears it (per
   * yuv_buf_hal_start_yuv_mode()'s
   * "yuv_buf_ll_enable_yuv_buf_mode(hw); yuv_buf_ll_disable_h264_
   * encode_mode(hw);" pairing -- YUV direct-capture and H264 encode are
   * mutually exclusive hardware modes). */
  bk7258_sim_poke32(TEST_YUV_BUF_CTRL, TEST_YUV_BUF_CTRL_H264_MODE);

  bk7258_yuv_buf_start();

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_YUV_MODE) != 0,
        "expected start() to set yuv_mode, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_H264_MODE) == 0,
        "expected start() to clear h264_mode, ctrl=0x%x", ctrl);
}

static void test_stop_clears_yuv_mode(void)
{
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_yuv_buf_start();
  CHECK((bk7258_sim_peek32(TEST_YUV_BUF_CTRL) &
         TEST_YUV_BUF_CTRL_YUV_MODE) != 0, "expected yuv_mode set");

  bk7258_yuv_buf_stop();

  ctrl = bk7258_sim_peek32(TEST_YUV_BUF_CTRL);
  CHECK((ctrl & TEST_YUV_BUF_CTRL_YUV_MODE) == 0,
        "expected stop() to clear yuv_mode, ctrl=0x%x", ctrl);
}

static void test_init_soft_resets_and_enables_irq(void)
{
  bk7258_sim_reset();

  bk7258_yuv_buf_init();

  /* init() must leave global_ctrl's soft_reset bit cleared afterward
   * (it pulses the reset, then clears it) -- a reset bit stuck set
   * would keep the peripheral held in reset. */
  CHECK((bk7258_sim_peek32(TEST_YUV_BUF_GLOBAL_CTRL) &
         TEST_YUV_BUF_GLOBAL_CTRL_SOFT_RESET) == 0,
        "expected soft_reset bit to be cleared after init() completes "
        "the reset pulse");
  CHECK(bk7258_sim_irq_is_enabled(BK7258_IRQ_YUVB) == true,
        "expected init() to call up_enable_irq(BK7258_IRQ_YUVB)");
}

static int g_line_cb_count;
static void *g_line_cb_arg_seen;

static void test_line_cb(void *arg)
{
  g_line_cb_count++;
  g_line_cb_arg_seen = arg;
}

static void test_isr_dispatches_on_sm0_wr(void)
{
  int dummy = 7;
  bool fired;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, &dummy);
  g_line_cb_count = 0;
  g_line_cb_arg_seen = NULL;

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_YUV_BUF_INT_STATUS_SM0_WR);
  fired = bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  CHECK(fired == true, "expected an ISR registered for IRQ_YUVB");
  CHECK(g_line_cb_count == 1,
        "expected the line callback to fire exactly once on sm0_wr_int, "
        "got %d calls", g_line_cb_count);
  CHECK(g_line_cb_arg_seen == &dummy,
        "expected the callback to receive the exact registered arg "
        "pointer");
}

static void test_isr_dispatches_on_sm1_wr(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, NULL);
  g_line_cb_count = 0;

  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, TEST_YUV_BUF_INT_STATUS_SM1_WR);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  CHECK(g_line_cb_count == 1,
        "expected the line callback to fire on sm1_wr_int (the other "
        "ping-pong buffer half) too, got %d calls", g_line_cb_count);
}

static void test_isr_does_not_dispatch_on_unrelated_status_bits(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, NULL);
  g_line_cb_count = 0;

  /* yuv_arv_int (frame-complete) is intentionally NOT handled by this
   * bring-up-scoped driver (see bk7258_yuv_buf.h's documented reduced
   * scope: only line-done events are wired up).  The ISR must not
   * mistake this bit for a line-done event. */
  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                     TEST_YUV_BUF_INT_STATUS_YUV_ARV);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  CHECK(g_line_cb_count == 0,
        "expected the line callback NOT to fire for yuv_arv_int (frame "
        "complete), which this driver does not handle -- got %d calls",
        g_line_cb_count);
}

static void test_isr_clears_status_via_write_back(void)
{
  uint32_t status_after;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, NULL);

  /* Seed both sm0_wr and an unrelated bit; the ISR must write back
   * exactly the value it read (write-1-to-clear per
   * yuv_buf_ll_clear_interrupt_status()'s "REG_WRITE(YUV_BUF_R_INT_
   * STATUS, int_status)" -- writing back the read value clears every
   * bit that was set, and only those). */
  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                     TEST_YUV_BUF_INT_STATUS_SM0_WR |
                     TEST_YUV_BUF_INT_STATUS_YUV_ARV);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  status_after = bk7258_sim_peek32(TEST_YUV_BUF_INT_STATUS);
  CHECK(status_after == 0u,
        "expected the ISR to clear every bit that was set by writing "
        "the read value back (write-1-to-clear), status_after=0x%x",
        status_after);
}

static void test_multiple_line_interrupts_accumulate_correctly(void)
{
  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, NULL);
  g_line_cb_count = 0;

  /* A 640x480 frame needs 480/8=60 line-done interrupts to assemble
   * (this driver's bring-up scope only validates that a single such
   * interrupt is dispatched correctly, per its documented reduced
   * scope -- but nothing should break if the same ISR fires repeatedly
   * across many simulated line-done events, which this test checks as
   * a basic robustness property). */
  for (int i = 0; i < 60; i++)
    {
      bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                         (i % 2 == 0) ? TEST_YUV_BUF_INT_STATUS_SM0_WR :
                                        TEST_YUV_BUF_INT_STATUS_SM1_WR);
      (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);
    }

  CHECK(g_line_cb_count == 60,
        "expected the line callback to fire exactly once per simulated "
        "line-done interrupt across 60 alternating sm0/sm1 events "
        "(matching a full 640x480 frame's 480/8=60 line batches), got "
        "%d", g_line_cb_count);
}

int main(void)
{
  test_configure_640x480_pixel_register();
  test_configure_other_resolutions();
  test_configure_writes_fixed_psram_line_buffer_address();
  test_get_line_buf_addr_matches_register_value();
  test_configure_enables_line_done_interrupts();
  test_start_sets_yuv_mode_clears_h264_mode();
  test_stop_clears_yuv_mode();
  test_init_soft_resets_and_enables_irq();
  test_isr_dispatches_on_sm0_wr();
  test_isr_dispatches_on_sm1_wr();
  test_isr_does_not_dispatch_on_unrelated_status_bits();
  test_isr_clears_status_via_write_back();
  test_multiple_line_interrupts_accumulate_correctly();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_yuv_buf.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

