static void test_isr_clears_status_via_write_back(void)
{
  uint32_t seeded_status;
  uint32_t status_after;

  bk7258_sim_reset();
  bk7258_yuv_buf_init();
  bk7258_yuv_buf_set_line_callback(test_line_cb, NULL);

  /* Seed both sm0_wr and an unrelated bit.  Note on what this test can
   * and cannot verify with a plain read/write mock register (as opposed
   * to real write-1-to-clear hardware semantics, which this harness
   * does not model): the driver's putreg32(status, YUV_BUF_INT_STATUS)
   * call writes the *exact value it read* back to the same address, so
   * in this mock the register's stored value after the ISR runs is
   * unchanged from what was seeded -- that IS the correct, verifiable
   * behavior for this driver (per yuv_buf_ll_clear_interrupt_status()'s
   * "REG_WRITE(YUV_BUF_R_INT_STATUS, int_status)": write back exactly
   * what was read).  On real write-1-to-clear hardware, writing a 1 to
   * a status bit clears that bit as a side effect of the write
   * transaction; this mock's plain-memory semantics cannot reproduce
   * that hardware side effect, so this test instead verifies the
   * *driver's* observable contract: it must write back precisely the
   * value it read (not a hand-picked subset, not the complement, not a
   * stale value), which is the part of the write-1-to-clear contract
   * entirely within this driver's control and thus the correct thing
   * for a driver-logic test to check. */
  seeded_status = TEST_YUV_BUF_INT_STATUS_SM0_WR |
                   TEST_YUV_BUF_INT_STATUS_YUV_ARV;
  bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS, seeded_status);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);

  status_after = bk7258_sim_peek32(TEST_YUV_BUF_INT_STATUS);
  CHECK(status_after == seeded_status,
        "expected the ISR to write back exactly the status value it "
        "read (0x%x) to acknowledge it, got 0x%x after the ISR ran "
        "(a real write-1-to-clear register would then read back 0 on "
        "actual hardware, but this driver-logic test verifies the "
        "driver issued the correct acknowledgment write, which this "
        "plain-memory mock register does not itself model as clearing)",
        seeded_status, status_after);
}

