const gsensor_device_t gs_sc7a20 =
{
    .name = "sc7a20",
    .init = sc7a20_init,
    .deinit = sc7a20_deinit,
    .open = sc7a20_open,
    .close = sc7a20_close,
    .setDatarate = sc7a20_setDatarate,
    .setMode = sc7a20_setMode,
    .setDataRange = sc7a20_setDataRange,
    .registerCallback = sc7a20_registerCallback,
