{
    I2C_LOGV("bk_i2c_get_busstate[%d].\n",s_i2c[id].master_status);
	if(s_i2c[id].master_status==0){
		return 1;//idle
		} else {
		return 0;//busy
	}
}

uint8_t bk_i2c_get_transstate ( int id )
{
    return i2ccallback[id].transtate;
}

