void i2c_hal_backup(i2c_hal_t *hal, uint32_t *pm_backup)
{
	i2c_ll_backup(&hal->hw, hal->id, pm_backup);
}

void i2c_hal_restore(i2c_hal_t *hal, uint32_t *pm_backup)
{
	i2c_ll_restore(&hal->hw, hal->id, pm_backup);
}
