/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/sim_tests_gc2145/test_gc2145.c
 *
 * Integration test for bk7258_gc2145.c, compiled against the real
 * production source (unmodified) plus the real bk7258_gpio.c/
 * bk7258_i2c_sim.c/bk7258_dma.c/bk7258_yuv_buf.c drivers, using the same
 * mock register/IRQ infrastructure as board/beken/chips/bk7258/
 * sim_tests/.
 *
 * A mock I2C slave (reusing the same bit-level state machine approach as
 * board/beken/chips/bk7258/sim_tests/test_i2c_sim.c, duplicated here
 * rather than shared via a header because it is test-local logic, not
 * production code) answers every one of the 625 real GC2145 init/
 * resolution register writes with a valid ACK, so this test exercises
 * the driver's actual end-to-end call sequence: power-on -> pinmux ->
 * i2c init -> write full init table -> write resolution table ->
 * yuv_buf init/configure -> dma init -> yuv_buf start.
 *
 * The line-done interrupt wait loop in bk7258_gc2145_test() is a
 * blocking busy-wait with no real asynchrony in this single-threaded
 * test process (up_udelay() is a no-op stub, and there is no timer
 * thread to fire bk7258_sim_irq_fire() *during* the wait).  This test
 * therefore pre-arms the mock YUV_BUF/DMA interrupt state *before*
 * calling bk7258_gc2145_test(), using a write hook on the YUV_BUF start
 * register (ctrl.yuv_mode) to fire the line-done interrupt synchronously
 * the moment the driver calls bk7258_yuv_buf_start() -- and another hook
 * on the DMA ctrl register to fire the DMA-done interrupt synchronously
 * the moment the driver calls bk7258_dma_start() -- so by the time
 * either wait loop's *first* condition check runs, the flag it is
 * waiting on is already set.  This validates the exact same call
 * sequence and control flow the real driver uses, without needing to
 * modify bk7258_gc2145.c to be testable or spin up real threads.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "hardware/bk7258_gpio.h"
#include "bk7258_gpio.h"
#include "bk7258_i2c_sim.h"
#include "bk7258_yuv_buf.h"
#include "bk7258_dma.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

#define I2C_SIM_SCL_PIN 0u
#define I2C_SIM_SDA_PIN 1u
#define GC2145_I2C_ADDR_BYTE (0x3Cu << 1)

/* Register layout constants duplicated from the production drivers'
 * private #defines, for the same "independent cross-check" reason
 * documented in test_dma.c/test_yuv_buf.c. */
#define TEST_YUV_BUF_CTRL          (0x48020000u + 4u * 4u)
#define TEST_YUV_BUF_CTRL_YUV_MODE (1u << 0)
#define TEST_YUV_BUF_INT_STATUS    (0x48020000u + 10u * 4u)
#define TEST_YUV_BUF_INT_STATUS_SM0_WR (1u << 2)

#define TEST_DMA_CTRL              (0x45020000u + 0x40u + 0u * 4u)
#define TEST_DMA_CTRL_ENABLE       (1u << 0)
#define TEST_DMA_STATUS            (0x45020000u + 0x40u + 12u * 4u)
#define TEST_DMA_STATUS_FINISH_INT (1u << 18)

/* ========================================================================
 * Mock I2C slave (same design as
 * board/beken/chips/bk7258/sim_tests/test_i2c_sim.c's mock slave;
 * duplicated rather than shared -- see file header comment).
 * ======================================================================== */

typedef enum
{
  SLAVE_IDLE,
  SLAVE_ADDR_BIT,
  SLAVE_ADDR_ACK,
  SLAVE_DATA_BIT,
  SLAVE_DATA_ACK
} slave_state_t;

typedef struct
{
  slave_state_t state;
  uint8_t bit_count;
  uint8_t shift_reg;
  bool last_scl;
  bool last_sda;
  bool skip_next_scl_falling;
  bool in_read_hook_writeback;
  bool addr_matched_this_txn;
  unsigned int bytes_seen;
  unsigned int transactions_seen;
} mock_slave_t;

static mock_slave_t g_slave;

static void mock_slave_reset(void)
{
  memset(&g_slave, 0, sizeof(g_slave));
  g_slave.state = SLAVE_IDLE;
}

static void mock_slave_write_hook(uintptr_t addr, uint32_t value, void *arg)
{
  bool scl;
  bool sda;
  bool scl_falling;

  (void)arg;

  if (g_slave.in_read_hook_writeback)
    {
      return;
    }

  if (addr == BK7258_GPIO_CFG(I2C_SIM_SCL_PIN))
    {
      scl = (value & BK7258_GPIO_OUTPUT) != 0;
    }
  else if (addr == BK7258_GPIO_CFG(I2C_SIM_SDA_PIN))
    {
      scl = g_slave.last_scl;
    }
  else
    {
      return;
    }

  sda = (bk7258_sim_peek32(BK7258_GPIO_CFG(I2C_SIM_SDA_PIN)) &
         BK7258_GPIO_OUTPUT) != 0;

  scl_falling = !scl && g_slave.last_scl;

  if (scl && g_slave.last_scl && !sda && g_slave.last_sda)
    {
      g_slave.state = SLAVE_ADDR_BIT;
      g_slave.bit_count = 0;
      g_slave.shift_reg = 0;
      g_slave.addr_matched_this_txn = false;
      g_slave.skip_next_scl_falling = true;
      g_slave.transactions_seen++;
    }
  else if (scl && g_slave.last_scl && sda && !g_slave.last_sda)
    {
      g_slave.state = SLAVE_IDLE;
    }
  else if (scl_falling && g_slave.skip_next_scl_falling)
    {
      g_slave.skip_next_scl_falling = false;
    }
  else if (scl_falling)
    {
      switch (g_slave.state)
        {
        case SLAVE_ADDR_BIT:
          g_slave.shift_reg = (uint8_t)((g_slave.shift_reg << 1) |
                                         (g_slave.last_sda ? 1 : 0));
          g_slave.bit_count++;
          if (g_slave.bit_count == 8)
            {
              g_slave.bytes_seen++;
              g_slave.addr_matched_this_txn =
                ((g_slave.shift_reg & 0xfeu) ==
                 (GC2145_I2C_ADDR_BYTE & 0xfeu));
              g_slave.state = SLAVE_ADDR_ACK;
            }
          break;

        case SLAVE_ADDR_ACK:
          g_slave.state = SLAVE_DATA_BIT;
          g_slave.bit_count = 0;
          g_slave.shift_reg = 0;
          break;

        case SLAVE_DATA_BIT:
          g_slave.shift_reg = (uint8_t)((g_slave.shift_reg << 1) |
                                         (g_slave.last_sda ? 1 : 0));
          g_slave.bit_count++;
          if (g_slave.bit_count == 8)
            {
              g_slave.bytes_seen++;
              g_slave.state = SLAVE_DATA_ACK;
            }
          break;

        case SLAVE_DATA_ACK:
          g_slave.state = SLAVE_DATA_BIT;
          g_slave.bit_count = 0;
          g_slave.shift_reg = 0;
          break;

        case SLAVE_IDLE:
        default:
          break;
        }
    }

  g_slave.last_scl = scl;
  g_slave.last_sda = sda;
}

static uint32_t mock_slave_read_hook(uintptr_t addr, uint32_t stored_value,
                                      void *arg)
{
  uint32_t driven_value;

  (void)arg;

  if (addr != BK7258_GPIO_CFG(I2C_SIM_SDA_PIN))
    {
      return stored_value;
    }

  if (g_slave.state == SLAVE_ADDR_ACK || g_slave.state == SLAVE_DATA_ACK)
    {
      driven_value = g_slave.addr_matched_this_txn ? 0u : BK7258_GPIO_INPUT;
    }
  else
    {
      return stored_value;
    }

  g_slave.in_read_hook_writeback = true;
  bk7258_sim_poke32(addr, ((driven_value & BK7258_GPIO_INPUT) != 0) ?
                     (BK7258_GPIO_INPUT | BK7258_GPIO_OUTPUT) : 0u);
  g_slave.in_read_hook_writeback = false;
  g_slave.last_sda = (driven_value & BK7258_GPIO_INPUT) != 0;

  return driven_value;
}

/* Always-NACK variant for test_gc2145_aborts_when_sensor_never_acks():
 * unconditionally drives SDA released/high (NACK) during any ACK
 * window the state machine detects, regardless of address matching --
 * see that test's comment for why this is more faithful than omitting
 * a read hook entirely. */
static uint32_t mock_slave_always_nack_read_hook(uintptr_t addr,
                                                  uint32_t stored_value,
                                                  void *arg)
{
  (void)arg;

  if (addr != BK7258_GPIO_CFG(I2C_SIM_SDA_PIN))
    {
      return stored_value;
    }

  if (g_slave.state != SLAVE_ADDR_ACK && g_slave.state != SLAVE_DATA_ACK)
    {
      return stored_value;
    }

  g_slave.in_read_hook_writeback = true;
  bk7258_sim_poke32(addr, BK7258_GPIO_INPUT | BK7258_GPIO_OUTPUT);
  g_slave.in_read_hook_writeback = false;
  g_slave.last_sda = true;

  return BK7258_GPIO_INPUT;
}

/* ========================================================================
 * Interrupt auto-fire hooks: the moment the driver writes the "start"
 * bit for YUV_BUF or DMA, synchronously fire that peripheral's
 * interrupt, so bk7258_gc2145_test()'s busy-wait loops see their flag
 * already set on the very first check (see file header comment for why
 * this is necessary in a single-threaded test process).
 * ======================================================================== */

static bool g_yuvb_auto_fire_armed;
static bool g_dma_auto_fire_armed;

static void irq_autofire_write_hook(uintptr_t addr, uint32_t value,
                                     void *arg)
{
  (void)arg;

  mock_slave_write_hook(addr, value, NULL);

  if (g_yuvb_auto_fire_armed && addr == TEST_YUV_BUF_CTRL &&
      (value & TEST_YUV_BUF_CTRL_YUV_MODE) != 0)
    {
      bk7258_sim_poke32(TEST_YUV_BUF_INT_STATUS,
                         TEST_YUV_BUF_INT_STATUS_SM0_WR);
      (void)bk7258_sim_irq_fire(BK7258_IRQ_YUVB);
    }

  if (g_dma_auto_fire_armed && addr == TEST_DMA_CTRL &&
      (value & TEST_DMA_CTRL_ENABLE) != 0)
    {
      bk7258_sim_poke32(TEST_DMA_STATUS, TEST_DMA_STATUS_FINISH_INT);
      (void)bk7258_sim_irq_fire(BK7258_IRQ_DMA);
    }
}

extern int bk7258_gc2145_test(int argc, char **argv);

static void test_gc2145_full_flow_with_responsive_sensor(void)
{
  int ret;

  bk7258_sim_reset();
  mock_slave_reset();
  g_yuvb_auto_fire_armed = true;
  g_dma_auto_fire_armed = true;
  bk7258_sim_set_write_hook(irq_autofire_write_hook, NULL);
  bk7258_sim_set_read_hook(mock_slave_read_hook, NULL);

  ret = bk7258_gc2145_test(0, NULL);

  CHECK(ret == 0,
        "expected bk7258_gc2145_test() to return 0 (success) when the "
        "mock I2C slave ACKs every register and both the YUV_BUF "
        "line-done and DMA-done interrupts fire promptly, got %d", ret);

  /* 625 = 585 (sensor_gc2145_init_talbe) + 40
   * (sensor_gc2145_640_480_table) register writes, each contributing 2
   * bytes on the wire (register address + value) plus 1 address byte
   * per transaction = 3 bytes/transaction * 625 transactions = 1875
   * bytes total observed by the mock slave. */
  CHECK(g_slave.transactions_seen == 625u,
        "expected exactly 625 I2C transactions (585 init + 40 "
        "resolution register writes), observed %u",
        g_slave.transactions_seen);
  CHECK(g_slave.bytes_seen == 625u * 3u,
        "expected exactly %u bytes clocked onto the bus (625 "
        "transactions * 3 bytes each: address, register, value), "
        "observed %u", 625u * 3u, g_slave.bytes_seen);
}

static void test_gc2145_aborts_when_sensor_never_acks(void)
{
  int ret;

  bk7258_sim_reset();
  mock_slave_reset();
  g_yuvb_auto_fire_armed = false;
  g_dma_auto_fire_armed = false;

  /* Install the same mock slave used by the "responsive sensor" test,
   * but never let it match any address: forcing addr_matched_this_txn
   * to always be false regardless of what byte was clocked in models a
   * sensor that is present on the bus electrically (so SCL/SDA edges
   * are observed normally) but never ACKs -- e.g. wrong I2C address,
   * or a sensor IC that is unpowered and so cannot pull SDA low no
   * matter what the master sends.  This is done via a read hook that
   * always drives NACK (SDA released/high) during any ACK window,
   * rather than omitting the read hook entirely -- omitting it left
   * SDA's mock-memory value in an unpredictable idle state, that
   * happened to equal 0 (interpreted as an incidental ACK) purely
   * because of what bit value the address byte's last bit had, which
   * is exactly the kind of coincidental pass this test must not rely
   * on. */
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);
  bk7258_sim_set_read_hook(mock_slave_always_nack_read_hook, NULL);

  ret = bk7258_gc2145_test(0, NULL);

  CHECK(ret == -1,
        "expected bk7258_gc2145_test() to return -1 when the sensor "
        "never ACKs any I2C write (modeling an absent/miswired/"
        "unpowered sensor), got %d", ret);
  CHECK(g_slave.transactions_seen == 1u,
        "expected the driver to abort after exactly 1 I2C transaction "
        "(the very first init register write, 0xFE) once it sees a "
        "NACK, rather than continuing through the rest of the 625-entry "
        "table, observed %u transactions", g_slave.transactions_seen);
  CHECK(g_slave.bytes_seen == 1u,
        "expected exactly 1 byte (the address byte of the aborted "
        "first transaction) to have been clocked onto the bus before "
        "the driver aborted on NACK, observed %u bytes",
        g_slave.bytes_seen);
}

static void test_gc2145_powers_on_camera_before_any_i2c_traffic(void)
{
  bk7258_sim_reset();
  mock_slave_reset();
  g_yuvb_auto_fire_armed = true;
  g_dma_auto_fire_armed = true;
  bk7258_sim_set_write_hook(irq_autofire_write_hook, NULL);
  bk7258_sim_set_read_hook(mock_slave_read_hook, NULL);

  (void)bk7258_gc2145_test(0, NULL);

  /* DVP_POWER_PIN is GPIO28 per bk7258_gc2145.c's documented
   * CONFIG_DVP_CTRL_POWER_GPIO_ID=28 citation; verify it ends up driven
   * high (the driver's bk7258_gc2145_power_on() calls
   * bk7258_gpio_output(DVP_POWER_PIN, true) and never turns it back off
   * within this test entry point, since there is no corresponding
   * power-down call in bk7258_gc2145_test()). */
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(28u)) & BK7258_GPIO_OUTPUT) != 0,
