static void test_gc2145_configures_yuv_buf_for_640x480(void)
{
  uint32_t pixel_reg;

  bk7258_sim_reset();
  mock_slave_reset();
  g_yuvb_auto_fire_armed = true;
  g_dma_auto_fire_armed = true;
