/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_i2c1.c
 *
 * Unit tests for bk7258_i2c1.c, compiled against the real production
 * source (bk7258_i2c1.c + bk7258_gpio.c, unmodified).
 *
 * Test strategy: a mock I2C1 slave observes writes to
 * BK7258_I2C1_SM_BUS_DATA and BK7258_I2C1_INT_STATUS's start bit, and
 * synchronously fires the I2C1 ISR with an ACK or NACK result -- see
 * board/beken/boards/bk7258/bk7258-ap/src/sim_tests_gc2145/test_gc2145.c's
 * file header for the full rationale (this file's mock slave is the
 * same design, duplicated here rather than shared via a header because
 * it is test-local logic).  Unlike that integration test (which only
 * checks bk7258_gc2145_test()'s overall return value and I2C
 * transaction/byte counts), this file additionally verifies
 * bk7258_i2c1_init()'s exact register configuration (pinmux function
 * index, sm_bus_cfg field values, peripheral enable) and
 * bk7258_i2c1_write_reg()'s per-transaction register-write sequence
 * (device address byte value, register/data byte values, STOP
 * condition), independently cross-checking the driver's own #define
 * bit-position math against hand-computed expected register values.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "sim_stubs.h"
#include "hardware/bk7258_gpio.h"
#include "hardware/bk7258_i2c1.h"
#include "bk7258_i2c1.h"
#include "irq.h"

static int g_failures;

#define CHECK(cond, ...) \
  do \
    { \
      if (!(cond)) \
        { \
          g_failures++; \
          printf("FAIL %s:%d: ", __func__, __LINE__); \
          printf(__VA_ARGS__); \
          printf("\n"); \
        } \
    } \
  while (0)

#define TEST_SLAVE_ADDR   0x3Cu
#define TEST_ADDR_BYTE    (TEST_SLAVE_ADDR << 1)

/* ========================================================================
 * Mock I2C1 hardware slave (same design as test_gc2145.c's; see that
 * file's header comment for the full rationale).
 * ======================================================================== */

typedef enum
{
  SLAVE_IDLE,
  SLAVE_GOT_ADDR,
  SLAVE_GOT_REG
} slave_state_t;

typedef struct
{
  slave_state_t state;
  bool always_nack;
  unsigned int transactions_seen;
  unsigned int bytes_seen;
  uint8_t last_reg_byte;
  uint8_t last_data_byte;
} mock_slave_t;

static mock_slave_t g_slave;

static void mock_slave_reset(void)
{
  memset(&g_slave, 0, sizeof(g_slave));
  g_slave.state = SLAVE_IDLE;
}

static void mock_slave_ack_and_fire(bool ack)
{
  uint32_t status = BK7258_I2C1_STATUS_SM_INT;

  if (ack)
    {
      status |= BK7258_I2C1_STATUS_ACK;
    }

  bk7258_sim_poke32(BK7258_I2C1_INT_STATUS, status);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_I2C1);
}

static void mock_slave_write_hook(uintptr_t addr, uint32_t value, void *arg)
{
  (void)arg;

  if (addr == BK7258_I2C1_INT_STATUS &&
      (value & BK7258_I2C1_STATUS_START) != 0)
    {
      uint32_t addr_byte = bk7258_sim_peek32(BK7258_I2C1_SM_BUS_DATA) &
                            BK7258_I2C1_DATA_MASK;

      g_slave.transactions_seen++;
      g_slave.bytes_seen++;

      if (g_slave.always_nack ||
          (addr_byte & 0xfeu) != (TEST_ADDR_BYTE & 0xfeu))
        {
          g_slave.state = SLAVE_IDLE;
          mock_slave_ack_and_fire(false);
          return;
        }

      g_slave.state = SLAVE_GOT_ADDR;
      mock_slave_ack_and_fire(true);
      return;
    }

  if (addr != BK7258_I2C1_SM_BUS_DATA || g_slave.state == SLAVE_IDLE)
    {
      return;
    }

  g_slave.bytes_seen++;

  switch (g_slave.state)
    {
      case SLAVE_GOT_ADDR:
        g_slave.last_reg_byte = (uint8_t)(value & BK7258_I2C1_DATA_MASK);
        g_slave.state = SLAVE_GOT_REG;
        mock_slave_ack_and_fire(true);
        break;

      case SLAVE_GOT_REG:
        g_slave.last_data_byte = (uint8_t)(value & BK7258_I2C1_DATA_MASK);
        g_slave.state = SLAVE_IDLE;
        mock_slave_ack_and_fire(true);
        break;

      case SLAVE_IDLE:
      default:
        break;
    }
}

/* ========================================================================
 * Tests
 * ======================================================================== */

static void test_init_configures_pinmux_for_gpio42_43(void)
{
  uint32_t scl_mux;
  uint32_t sda_mux;

  bk7258_sim_reset();
  mock_slave_reset();

  bk7258_i2c1_init();

  /* GPIO42/43's pinmux-select field is a 4-bit-per-pin index into
   * BK7258_GPIO_SYS_CFG; function index 0 selects I2C1_SCL/I2C1_SDA per
   * gpio_map.h's per-pin function array (see bk7258_i2c1.c's
   * BK7258_I2C1_PINMUX_FUNCTION comment). */
  scl_mux = (bk7258_sim_peek32(BK7258_GPIO_SYS_CFG(42u)) &
             BK7258_GPIO_SYS_MASK(42u)) >> BK7258_GPIO_SYS_SHIFT(42u);
  sda_mux = (bk7258_sim_peek32(BK7258_GPIO_SYS_CFG(43u)) &
             BK7258_GPIO_SYS_MASK(43u)) >> BK7258_GPIO_SYS_SHIFT(43u);

  CHECK(scl_mux == 0u,
        "expected GPIO42's pinmux function index to be 0 (I2C1_SCL), "
        "got %u", scl_mux);
  CHECK(sda_mux == 0u,
        "expected GPIO43's pinmux function index to be 0 (I2C1_SDA), "
        "got %u", sda_mux);

  /* bk7258_gpio_set_function() also sets SECOND_FUNCTION and clears
   * OUTPUT_DISABLE/INPUT_ENABLE/PULL_ENABLE on the GPIO_CFG register --
   * verify the mux takes effect on the actual pin config, not just the
   * SYS_CFG select field (a driver that wrote SYS_CFG but never called
   * the pinmux function would leave the pin as a plain GPIO and I2C1
   * would never actually drive/sense these pins). */
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(42u)) &
         BK7258_GPIO_SECOND_FUNCTION) != 0,
        "expected GPIO42 to have SECOND_FUNCTION set (routed to I2C1, "
        "not plain GPIO)");
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(43u)) &
         BK7258_GPIO_SECOND_FUNCTION) != 0,
        "expected GPIO43 to have SECOND_FUNCTION set (routed to I2C1, "
        "not plain GPIO)");
}

static void test_init_enables_peripheral_and_clock_bypass(void)
{
  uint32_t global_ctrl;
  uint32_t cfg;

  bk7258_sim_reset();
  mock_slave_reset();

  bk7258_i2c1_init();

  global_ctrl = bk7258_sim_peek32(BK7258_I2C1_GLOBAL_CTRL);
  CHECK((global_ctrl & BK7258_I2C1_CLK_GATE_BYPASS) != 0,
        "expected clk_gate_bypass=1 after init (required to read the "
        "ack bit in the ISR, per i2c_ll_enable()'s comment), got "
        "global_ctrl=0x%08x", global_ctrl);

  cfg = bk7258_sim_peek32(BK7258_I2C1_SM_BUS_CFG);
  CHECK((cfg & BK7258_I2C1_CFG_EN) != 0,
        "expected sm_bus_cfg.en=1 after init, got sm_bus_cfg=0x%08x",
        cfg);
  CHECK((cfg & BK7258_I2C1_CFG_TIMEOUT_EN) != 0,
        "expected sm_bus_cfg.timeout_en=1 after init, got "
        "sm_bus_cfg=0x%08x", cfg);
  CHECK((cfg & BK7258_I2C1_CFG_IDLE_DET_EN) != 0,
        "expected sm_bus_cfg.idle_det_en=1 after init, got "
        "sm_bus_cfg=0x%08x", cfg);
  CHECK((cfg & BK7258_I2C1_CFG_INH) == 0,
        "expected sm_bus_cfg.inh=0 after init (matching "
        "i2c_ll_enable_slave()'s clear, even though this driver never "
        "acts as a slave), got sm_bus_cfg=0x%08x", cfg);

  CHECK(bk7258_sim_irq_is_enabled(BK7258_IRQ_I2C1),
        "expected the I2C1 IRQ to be enabled after init");
}

static void test_write_reg_sends_correct_three_byte_sequence(void)
{
  bool ok;

  bk7258_sim_reset();
  mock_slave_reset();
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);

  bk7258_i2c1_init();
  ok = bk7258_i2c1_write_reg(TEST_SLAVE_ADDR, 0x42u, 0x99u);

  CHECK(ok, "expected bk7258_i2c1_write_reg() to return true when the "
        "mock slave ACKs all 3 bytes");
  CHECK(g_slave.transactions_seen == 1u,
        "expected exactly 1 I2C transaction, observed %u",
        g_slave.transactions_seen);
  CHECK(g_slave.bytes_seen == 3u,
        "expected exactly 3 bytes (address, register, data) clocked "
        "onto the bus, observed %u", g_slave.bytes_seen);
  CHECK(g_slave.last_reg_byte == 0x42u,
        "expected the register-address byte on the wire to be 0x42, "
        "got 0x%02x", g_slave.last_reg_byte);
  CHECK(g_slave.last_data_byte == 0x99u,
        "expected the data byte on the wire to be 0x99, got 0x%02x",
        g_slave.last_data_byte);
}

static void test_write_reg_returns_false_on_nack(void)
{
  bool ok;

  bk7258_sim_reset();
  mock_slave_reset();
  g_slave.always_nack = true;
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);

  bk7258_i2c1_init();
  ok = bk7258_i2c1_write_reg(TEST_SLAVE_ADDR, 0x42u, 0x99u);

  CHECK(!ok, "expected bk7258_i2c1_write_reg() to return false when "
        "the mock slave NACKs the address byte");
  CHECK(g_slave.transactions_seen == 1u,
        "expected exactly 1 I2C transaction attempted before "
        "returning, observed %u", g_slave.transactions_seen);
  CHECK(g_slave.bytes_seen == 1u,
        "expected only the address byte (1) to have been clocked "
        "before the NACK aborted the transaction, observed %u bytes",
        g_slave.bytes_seen);
}

static void test_write_reg_times_out_when_slave_never_responds(void)
{
  bool ok;

  bk7258_sim_reset();
  mock_slave_reset();
  /* No write hook installed at all: the mock slave never fires the
   * ISR, modeling a sensor that is completely absent from the bus
   * (e.g. wrong GPIO wiring) rather than one that is present and
   * actively NACKing. */

  bk7258_i2c1_init();
  ok = bk7258_i2c1_write_reg(TEST_SLAVE_ADDR, 0x42u, 0x99u);

  CHECK(!ok, "expected bk7258_i2c1_write_reg() to return false when no "
        "interrupt ever fires (simulating an absent/unwired slave), "
        "rather than hanging or crashing");
}

static void test_write_reg_recovers_after_a_timeout(void)
{
  bool first_ok;
  bool second_ok;

  bk7258_sim_reset();
  mock_slave_reset();

  bk7258_i2c1_init();

  /* First call: no write hook yet, so it times out (same scenario as
   * test_write_reg_times_out_when_slave_never_responds()). */
  first_ok = bk7258_i2c1_write_reg(TEST_SLAVE_ADDR, 0x42u, 0x99u);
  CHECK(!first_ok, "expected the first write_reg() call to time out "
        "with no mock slave installed");

  /* Second call: install the mock slave now, and verify the driver's
   * timeout-recovery path (disable+re-enable the peripheral, reset
   * state to IDLE) left the hardware in a state where a subsequent
   * transaction can still succeed, rather than being permanently
   * wedged after one timeout. */
  mock_slave_reset();
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);
  second_ok = bk7258_i2c1_write_reg(TEST_SLAVE_ADDR, 0x55u, 0xaau);

  CHECK(second_ok, "expected a write_reg() call after a prior timeout "
        "to still succeed once a slave is present, i.e. the timeout "
        "path must not leave the driver permanently wedged");
  CHECK(g_slave.last_reg_byte == 0x55u && g_slave.last_data_byte == 0xaau,
        "expected the second (post-timeout) transaction's bytes on "
        "the wire to be reg=0x55/data=0xaa, got reg=0x%02x/data=0x%02x",
        g_slave.last_reg_byte, g_slave.last_data_byte);
}

static void test_write_reg_rejects_wrong_slave_address(void)
{
  bool ok;

  bk7258_sim_reset();
  mock_slave_reset();
  bk7258_sim_set_write_hook(mock_slave_write_hook, NULL);

  bk7258_i2c1_init();
  /* 0x10 does not match TEST_SLAVE_ADDR (0x3C) that the mock slave
   * checks against, so this must NACK exactly like the
   * always_nack case, without needing that flag. */
  ok = bk7258_i2c1_write_reg(0x10u, 0x42u, 0x99u);

  CHECK(!ok, "expected bk7258_i2c1_write_reg() to return false when "
        "the device address does not match any slave on the bus");
  CHECK(g_slave.bytes_seen == 1u,
        "expected only the (unmatched) address byte to have been "
        "clocked before aborting, observed %u bytes",
        g_slave.bytes_seen);
}

int main(void)
{
  test_init_configures_pinmux_for_gpio42_43();
  test_init_enables_peripheral_and_clock_bypass();
  test_write_reg_sends_correct_three_byte_sequence();
  test_write_reg_returns_false_on_nack();
  test_write_reg_times_out_when_slave_never_responds();
  test_write_reg_recovers_after_a_timeout();
  test_write_reg_rejects_wrong_slave_address();

  if (g_failures == 0)
    {
      printf("PASS: all bk7258_i2c1.c tests passed\n");
      return 0;
    }

  printf("FAILED: %d assertion(s) failed\n", g_failures);
  return 1;
}

